INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51509, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "給食", "is_correct": true, "explanation": "正解。「きゅうしょく」と読む。"}, {"text": "急速", "is_correct": false, "explanation": "「きゅうそく」と読む。「しょ」が「そ」に変わる一モーラ差。"}, {"text": "昼食", "is_correct": false, "explanation": "「ちゅうしょく」と読む。最初の「きゅ」が「ちゅ」になる一モーラ差。"}, {"text": "修飾", "is_correct": false, "explanation": "「しゅうしょく」と読む。最初の「きゅ」が「しゅ」になる一モーラ差。"}, {"text": "教職", "is_correct": false, "explanation": "「きょうしょく」と読む。「きゅ」が「きょ」になる一モーラ差。"}], "explanations": {"給食": "正解。「きゅうしょく」と読む。", "急速": "「きゅうそく」と読む。「しょ」が「そ」に変わる一モーラ差。", "昼食": "「ちゅうしょく」と読む。最初の「きゅ」が「ちゅ」になる一モーラ差。", "修飾": "「しゅうしょく」と読む。最初の「きゅ」が「しゅ」になる一モーラ差。", "教職": "「きょうしょく」と読む。「きゅ」が「きょ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "給食"}, "level_3": {"options": [{"text": "給食", "is_correct": true, "explanation": "給食を配る係「給食当番」になる。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「天気当番」という係はない。"}, {"text": "宿題", "is_correct": false, "explanation": "意味：「宿題当番」という係は普通ない。"}, {"text": "体育", "is_correct": false, "explanation": "意味：「体育当番」は一般的な係でなく文に合わない。"}], "explanations": {"給食": "給食を配る係「給食当番」になる。", "天気": "意味：「天気当番」という係はない。", "宿題": "意味：「宿題当番」という係は普通ない。", "体育": "意味：「体育当番」は一般的な係でなく文に合わない。"}, "sentence_index": 6, "correct_answer": "給食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この学校の給食がおいしいを。", "explanation": "助詞の混同：文末に「を」は付かない。"}, {"text": "この学校は給食のおいしい。", "explanation": "語順・係り受けの誤り：述語が成り立たない。"}, {"text": "この学校の給食はおいしかったている。", "explanation": "活用の誤り：「おいしかったている」は誤った形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51509, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友だちに給食を食べている。", "corrected_sentence": "友だちと給食を食べている。", "error_description": "一緒に行う相手には「と」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51509, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「食べる」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「給食が食べている」では給食が食べる主体になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「給食に食べている」は着点を表し非文。"}, {"text": "へ", "is_correct": false, "explanation": "「給食へ食べている」は方向を表し非文。"}], "correct_answer": "を", "explanations": {"を": "「食べる」の目的語を示す。", "が": "「給食が食べている」では給食が食べる主体になり不自然。", "に": "「給食に食べている」は着点を表し非文。", "へ": "「給食へ食べている」は方向を表し非文。"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "合わせる", "is_correct": true, "explanation": "正解。「あわせる」と読む。"}, {"text": "慌てる", "is_correct": false, "explanation": "「あわてる」と読む。「せ」が「て」に変わる一モーラ差。"}, {"text": "浴びせる", "is_correct": false, "explanation": "「あびせる」と読む。「わ」が「び」に変わる一モーラ差。"}, {"text": "合わさる", "is_correct": false, "explanation": "「あわさる」と読む。「せ」が「さ」に変わる一モーラ差。"}, {"text": "焦る", "is_correct": false, "explanation": "「あせる」と読む。「わ」が抜けた一モーラ差。"}], "explanations": {"合わせる": "正解。「あわせる」と読む。", "慌てる": "「あわてる」と読む。「せ」が「て」に変わる一モーラ差。", "浴びせる": "「あびせる」と読む。「わ」が「び」に変わる一モーラ差。", "合わさる": "「あわさる」と読む。「せ」が「さ」に変わる一モーラ差。", "焦る": "「あせる」と読む。「わ」が抜けた一モーラ差。"}, "sentence_index": null, "correct_answer": "合わせる"}, "level_3": {"options": [{"text": "合わせる", "is_correct": true, "explanation": "両手をくっつけるので合う。"}, {"text": "投げる", "is_correct": false, "explanation": "意味：両手を投げることはできない。"}, {"text": "借りる", "is_correct": false, "explanation": "意味：自分の両手を借りるのは不自然。"}, {"text": "落とす", "is_correct": false, "explanation": "意味：両手を落とすは意味が通らない。"}], "explanations": {"合わせる": "両手をくっつけるので合う。", "投げる": "意味：両手を投げることはできない。", "借りる": "意味：自分の両手を借りるのは不自然。", "落とす": "意味：両手を落とすは意味が通らない。"}, "sentence_index": 0, "correct_answer": "合わせる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "板の端がぴったり合わせる。", "explanation": "助詞の混同：他動詞「合わせる」の目的語は「を」。"}, {"text": "板の端をぴったり合わせたている。", "explanation": "活用の誤り：「合わせたている」は誤り。"}, {"text": "ぴったり板の端を合わせるを。", "explanation": "語順・助詞の誤り：文末に「を」は付かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの箱をテープで合わせるた。", "corrected_sentence": "二つの箱をテープで合わせた。", "error_description": "「合わせるた」は誤った活用で、た形は「合わせた」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "合わせて", "is_correct": true, "explanation": "後ろの「はった」につなぐのでて形が必要。"}, {"text": "合わせる", "is_correct": false, "explanation": "辞書形では「はった」に続かない。"}, {"text": "合わせない", "is_correct": false, "explanation": "否定では紙をはる流れと矛盾する。"}, {"text": "合わせた", "is_correct": false, "explanation": "た形のままでは後ろに動詞を続けられない。"}], "correct_form": "合わせて", "base_form": "合わせる", "form_label": "て形", "sentence_index": 1, "explanations": {"合わせて": "後ろの「はった」につなぐのでて形が必要。", "合わせる": "辞書形では「はった」に続かない。", "合わせない": "否定では紙をはる流れと矛盾する。", "合わせた": "た形のままでは後ろに動詞を続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "他動詞「合わせる」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「紙に合わせて」では紙が基準の意味になり文意が変わる。"}, {"text": "で", "is_correct": false, "explanation": "「紙で合わせて」は手段となり、何を合わせたか分からない。"}, {"text": "へ", "is_correct": false, "explanation": "「紙へ合わせて」は方向で非文。"}], "correct_answer": "を", "explanations": {"を": "他動詞「合わせる」の目的語を示す。", "に": "「紙に合わせて」では紙が基準の意味になり文意が変わる。", "で": "「紙で合わせて」は手段となり、何を合わせたか分からない。", "へ": "「紙へ合わせて」は方向で非文。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "離す", "is_correct": true, "explanation": "くっついているものを分けることで、合わせるの対義。"}, {"text": "つなぐ", "is_correct": false, "explanation": "二つを結ぶことで、近い意味。"}, {"text": "並べる", "is_correct": false, "explanation": "順に置くことで、対義ではない。"}, {"text": "重ねる", "is_correct": false, "explanation": "上に置くことで、むしろ近い意味。"}], "correct_answer": "離す", "explanations": {"離す": "くっついているものを分けることで、合わせるの対義。", "つなぐ": "二つを結ぶことで、近い意味。", "並べる": "順に置くことで、対義ではない。", "重ねる": "上に置くことで、むしろ近い意味。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "合わせる", "is_correct": true, "explanation": "正解。「あわせる」と読む。"}, {"text": "任せる", "is_correct": false, "explanation": "「まかせる」と読む。「あわ」が「まか」に変わる。"}, {"text": "被せる", "is_correct": false, "explanation": "「かぶせる」と読む。「あわ」が「かぶ」に変わる。"}, {"text": "焦らせる", "is_correct": false, "explanation": "「あせらせる」と読む。音が似ているが別の語。"}], "explanations": {"合わせる": "正解。「あわせる」と読む。", "任せる": "「まかせる」と読む。「あわ」が「まか」に変わる。", "被せる": "「かぶせる」と読む。「あわ」が「かぶ」に変わる。", "焦らせる": "「あせらせる」と読む。音が似ているが別の語。"}, "sentence_index": null, "correct_answer": "合わせる"}, "level_3": {"options": [{"text": "合わせられる", "is_correct": true, "explanation": "布をくっつけることができるかを問う可能形。"}, {"text": "飲める", "is_correct": false, "explanation": "意味：布は飲めない。"}, {"text": "泳げる", "is_correct": false, "explanation": "文法：「泳げる」は「を」で布をとれない。"}, {"text": "眠れる", "is_correct": false, "explanation": "文法：「眠れる」は目的語をとれない。"}], "explanations": {"合わせられる": "布をくっつけることができるかを問う可能形。", "飲める": "意味：布は飲めない。", "泳げる": "文法：「泳げる」は「を」で布をとれない。", "眠れる": "文法：「眠れる」は目的語をとれない。"}, "sentence_index": 6, "correct_answer": "合わせられる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "穴が合わせないとねじが入らない。", "explanation": "助詞の混同：目的語は「を」。"}, {"text": "穴を合わせなかったとねじが入らない。", "explanation": "活用の誤り：条件「と」の前に過去形は使わない。"}, {"text": "ねじが穴を入らない合わせないと。", "explanation": "語順の誤り：文の構造が壊れている。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51517, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三人のお金を合わせるた。", "corrected_sentence": "三人のお金を合わせる。", "error_description": "「合わせるた」は誤った活用で、「合わせる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "合わせた", "is_correct": true, "explanation": "終わった動作を述べるのでた形。"}, {"text": "合わせ", "is_correct": false, "explanation": "連用形のままでは文が終わらない。"}, {"text": "合わせば", "is_correct": false, "explanation": "「合わせば」は正しい形でなく（「合わせれば」）、文も終わらない。"}, {"text": "合わせられ", "is_correct": false, "explanation": "連用形のままで文が終わらない。"}], "correct_form": "合わせた", "base_form": "合わせる", "form_label": "た形（過去）", "sentence_index": 7, "explanations": {"合わせた": "終わった動作を述べるのでた形。", "合わせ": "連用形のままでは文が終わらない。", "合わせば": "「合わせば」は正しい形でなく（「合わせれば」）、文も終わらない。", "合わせられ": "連用形のままで文が終わらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b098110-0885-40ef-b2ee-26dcaca0a304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
