INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35711, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "割合。率。特に、為替レートや料金など、交換や計算の基準となる比率。", "primary_collocate": null, "pronunciation": "れーと", "ipa": "ɾeːto", "syllable_count": 3, "sentences": [{"text": "今日のドルのレートを調べた。", "target_word": "レート", "complexity_tier": "T3", "furigana": "きょう しら", "sentence_source": "generated"}, {"text": "レートが上がって、旅行が高くなった。", "target_word": "レート", "complexity_tier": "T3", "furigana": "あ りょこう たか", "sentence_source": "generated"}, {"text": "銀行でレートを確認してください。", "target_word": "レート", "complexity_tier": "T3", "furigana": "ぎんこう かくにん", "sentence_source": "generated"}, {"text": "このレートはとても良い。", "target_word": "レート", "complexity_tier": "T3", "furigana": "よ", "sentence_source": "generated"}, {"text": "円のレートが毎日変わっている。", "target_word": "レート", "complexity_tier": "T3", "furigana": "えん まいにち か", "sentence_source": "generated"}, {"text": "空港のレートは少し悪い。", "target_word": "レート", "complexity_tier": "T3", "furigana": "くうこう すこ わる", "sentence_source": "generated"}, {"text": "レートの表を見せてもらった。", "target_word": "レート", "complexity_tier": "T3", "furigana": "ひょう み", "sentence_source": "generated"}, {"text": "父はいつもレートを気にしている。", "target_word": "レート", "complexity_tier": "T3", "furigana": "ちち き", "sentence_source": "generated"}, {"text": "良いレートで両替できた。", "target_word": "レート", "complexity_tier": "T3", "furigana": "よ りょうがえ", "sentence_source": "generated"}, {"text": "ニュースでレートの話を聞いた。", "target_word": "レート", "complexity_tier": "T3", "furigana": "はなし き", "sentence_source": "generated"}], "morphological_forms": [{"form": "為替レート", "label": "派生"}, {"form": "交換レート", "label": "派生"}, {"form": "レート表", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 交換や計算の基準となる比率", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'cl