INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35112, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある時よりも、もっと前のこと。", "primary_collocate": null, "pronunciation": "いぜん", "ipa": "izeɴ", "syllable_count": 3, "sentences": [{"text": "以前、この町に住んでいた。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん まち す", "sentence_source": "generated"}, {"text": "以前より日本語が上手になった。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん にほんご じょうず", "sentence_source": "generated"}, {"text": "以前の家は駅から遠かった。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん いえ えき とお", "sentence_source": "generated"}, {"text": "彼とは以前から友達だ。", "target_word": "以前", "complexity_tier": "T3", "furigana": "かれ いぜん ともだち", "sentence_source": "generated"}, {"text": "以前は毎朝走っていた。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん まいあさ はし", "sentence_source": "generated"}, {"text": "この店は以前と同じ味だ。", "target_word": "以前", "complexity_tier": "T3", "furigana": "みせ いぜん おな あじ", "sentence_source": "generated"}, {"text": "以前に会ったことがある。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん あ", "sentence_source": "generated"}, {"text": "十年以前の写真を見つけた。", "target_word": "以前", "complexity_tier": "T3", "furigana": "じゅうねん いぜん しゃしん み", "sentence_source": "generated"}, {"text": "以前の私は泳げなかった。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん わたし およ", "sentence_source": "generated"}, {"text": "それは以前聞いた話だ。", "target_word": "以前", "complexity_tier": "T3", "furigana": "いぜん き はなし", "sentence_source": "generated"}], "morphological_forms": [{"form": "以前から", "label": "派生"}, {"form": "以前は", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ある時よりも前の時", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c