INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "範囲や影響が大きくなったり、遠くまで届いたりする。", "primary_collocate": null, "pronunciation": "ひろがる", "ipa": "çiɾogaɾɯ", "syllable_count": 4, "sentences": [{"text": "そのうわさは学校中に広がった。", "target_word": "広がった", "complexity_tier": "T3", "furigana": "がっこうじゅう ひろ", "sentence_source": "generated"}, {"text": "ネットで話題が広がっている。", "target_word": "広がって", "complexity_tier": "T3", "furigana": "わだい ひろ", "sentence_source": "generated"}, {"text": "病気が国中に広がる。", "target_word": "広がる", "complexity_tier": "T3", "furigana": "びょうき くにじゅう ひろ", "sentence_source": "generated"}, {"text": "留学して世界が広がった。", "target_word": "広がった", "complexity_tier": "T3", "furigana": "りゅうがく せかい ひろ", "sentence_source": "generated"}, {"text": "この遊びは子どもの間で広がった。", "target_word": "広がった", "complexity_tier": "T3", "furigana": "あそ こ あいだ ひろ", "sentence_source": "generated"}, {"text": "友だちの輪が広がっていく。", "target_word": "広がって", "complexity_tier": "T3", "furigana": "とも わ ひろ", "sentence_source": "generated"}, {"text": "広がる人気に店も驚いた。", "target_word": "広がる", "complexity_tier": "T3", "furigana": "ひろ にんき みせ おどろ", "sentence_source": "generated"}, {"text": "新しい考えはなかなか広がらない。", "target_word": "広がらない", "complexity_tier": "T3", "furigana": "あたら かんが ひろ", "sentence_source": "generated"}, {"text": "本を読むと興味が広がる。", "target_word": "広がる", "complexity_tier": "T3", "furigana": "ほん よ きょうみ ひろ", "sentence_source": "generated"}, {"text": "二人の差がまた広がった。", "target_word": "広がった", "complexity_tier": "T3", "furigana": "ふたり さ ひろ", "sentence_source": "generated"}], "morphological_forms": [{"form": "広がった", "label": "活用"}, {"form": "広がって", "label": "活用"}, {"form": "広がらない", "label": "活用"}, {"form": "広がり", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 範囲や影響がより大きくなる", "collocate_grounding": {"status": "no_source", "reas