INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35156, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "道や線などが、とぎれずに目的の所までつながる。", "primary_collocate": null, "pronunciation": "つうずる", "ipa": "tsɯːzɯɾɯ", "syllable_count": 4, "sentences": [{"text": "この道は駅に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "みち えき つう", "sentence_source": "generated"}, {"text": "すべての道はローマに通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "みち つう", "sentence_source": "generated"}, {"text": "海に通ずる川を下った。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "うみ つう かわ くだ", "sentence_source": "generated"}, {"text": "地下道は隣の駅に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "ちかどう となり えき つう", "sentence_source": "generated"}, {"text": "裏の門は公園に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "うら もん こうえん つう", "sentence_source": "generated"}, {"text": "山へ通ずる道は細い。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "やま つう みち ほそ", "sentence_source": "generated"}, {"text": "このトンネルは町に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "まち つう", "sentence_source": "generated"}, {"text": "二階に通ずる階段がある。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "にかい つう かいだん", "sentence_source": "generated"}, {"text": "村へ通ずる橋が新しくなった。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "むら つう はし あたら", "sentence_source": "generated"}, {"text": "その廊下は庭に通ずる。", "target_word": "通ずる", "complexity_tier": "T3", "furigana": "ろうか にわ つう", "sentence_source": "generated"}], "morphological_forms": [{"form": "通じる", "label": "派生"}, {"form": "通じた", "label": "活用"}, {"form": "通じて", "label": "活用"}, {"form": "通じない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 道などが途切れずある所へつながる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserte