INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以前", "is_correct": true, "explanation": "正解。「いぜん」と読む。"}, {"text": "意見", "is_correct": false, "explanation": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。"}, {"text": "遺伝", "is_correct": false, "explanation": "「いでん」と読み、「ぜ」が「で」に変わった一モーラ違いの語。"}, {"text": "自然", "is_correct": false, "explanation": "「しぜん」と読み、「い」が「し」に変わった一モーラ違いの語。"}, {"text": "威厳", "is_correct": false, "explanation": "「いげん」と読み、「ぜ」が「げ」に変わった一モーラ違いの語。"}], "explanations": {"以前": "正解。「いぜん」と読む。", "意見": "「いけん」と読み、「ぜ」が「け」に変わった一モーラ違いの語。", "遺伝": "「いでん」と読み、「ぜ」が「で」に変わった一モーラ違いの語。", "自然": "「しぜん」と読み、「い」が「し」に変わった一モーラ違いの語。", "威厳": "「いげん」と読み、「ぜ」が「げ」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "以前"}, "level_3": {"options": [{"text": "以前", "is_correct": true, "explanation": "「住んでいた」という過去の状態に合う。"}, {"text": "明日", "is_correct": false, "explanation": "過去形「住んでいた」と合わない。"}, {"text": "将来", "is_correct": false, "explanation": "未来を表し、過去形と矛盾する。"}, {"text": "今後", "is_correct": false, "explanation": "これから先を表し、過去形と合わない。"}], "explanations": {"以前": "「住んでいた」という過去の状態に合う。", "明日": "過去形「住んでいた」と合わない。", "将来": "未来を表し、過去形と矛盾する。", "今後": "これから先を表し、過去形と合わない。"}, "sentence_index": 0, "correct_answer": "以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "以前に駅へ行ってください。", "explanation": "「以前」は過去を表すので、これからの依頼には使えない。"}, {"text": "この本は以前がおもしろい。", "explanation": "「以前」を本の性質のように使っており意味が通らない。"}, {"text": "来週の以前に宿題を出す。", "explanation": "未来の時点「来週」と組み合わせる使い方は不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_