INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35113, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "より", "options": [{"text": "より", "is_correct": true, "explanation": "比較の基準を表し「以前より」で「前と比べて」の意味になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表す助詞で、この位置では非文。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、時を表す「以前」には付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、ここでは意味が通らない。"}], "correct_answer": "より", "explanations": {"より": "比較の基準を表し「以前より」で「前と比べて」の意味になる。", "を": "目的語を表す助詞で、この位置では非文。", "へ": "方向を表し、時を表す「以前」には付かない。", "で": "手段や場所を表し、ここでは意味が通らない。"}, "error_tags": {"を": "object_marking", "へ": "direction", "で": "instrument"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "以後", "is_correct": true, "explanation": "「以前」の反対で、ある時より後を表す。"}, {"text": "昔", "is_correct": false, "explanation": "「以前」とほぼ同じ意味で、反対ではない。"}, {"text": "前", "is_correct": false, "explanation": "「以前」と近い意味で、反対ではない。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表す語で、時の前後とは関係がない。"}], "correct_answer": "以後", "explanations": {"以後": "「以前」の反対で、ある時より後を表す。", "昔": "「以前」とほぼ同じ意味で、反対ではない。", "前": "「以前」と近い意味で、反対ではない。", "大きい": "大きさを表す語で、時の前後とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
