INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35132, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "正解。「よみかき」と読む。"}, {"text": "読み方", "is_correct": false, "explanation": "「よみかた」と読み、語末の「き」が「た」に変わった一モーラ違いの語。"}, {"text": "読みかけ", "is_correct": false, "explanation": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。"}, {"text": "横書き", "is_correct": false, "explanation": "「よこがき」と読み、「みか」が「こが」に変わった（二モーラ違いで判定で落ちうる）語。"}], "explanations": {"読み書き": "正解。「よみかき」と読む。", "読み方": "「よみかた」と読み、語末の「き」が「た」に変わった一モーラ違いの語。", "読みかけ": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。", "横書き": "「よこがき」と読み、「みか」が「こが」に変わった（二モーラ違いで判定で落ちうる）語。"}, "sentence_index": null, "correct_answer": "読み書き"}, "level_3": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "漢字を読んだり書いたりする練習として自然。"}, {"text": "料理", "is_correct": false, "explanation": "「漢字の料理」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「漢字の散歩」は意味をなさない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「漢字の洗濯」は不自然。"}], "explanations": {"読み書き": "漢字を読んだり書いたりする練習として自然。", "料理": "「漢字の料理」は意味が通らない。", "散歩": "「漢字の散歩」は意味をなさない。", "洗濯": "「漢字の洗濯」は不自然。"}, "sentence_index": 0, "correct_answer": "読み書き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "読み書きで駅まで歩いた。", "explanation": "「読み書き」を移動の手段のように使っており誤り。"}, {"text": "このスープは読み書きがする。", "explanation": "食べ物の性質のように使っていて意味が通らない。"}, {"text": "公園で読み書きを投げた。", "explanation": "物のように「投げる」の目的語にしており誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.genera