INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35133, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "正解。「よみかき」と読む。"}, {"text": "読み替え", "is_correct": false, "explanation": "「よみかえ」と読み、語末の「き」が「え」に変わった一モーラ違いの語。"}, {"text": "読みかけ", "is_correct": false, "explanation": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。"}, {"text": "縦書き", "is_correct": false, "explanation": "「たてがき」と読み、音の大きく異なる（判定で落ちうる）語。"}], "explanations": {"読み書き": "正解。「よみかき」と読む。", "読み替え": "「よみかえ」と読み、語末の「き」が「え」に変わった一モーラ違いの語。", "読みかけ": "「よみかけ」と読み、語末の「き」が「け」に変わった一モーラ違いの語。", "縦書き": "「たてがき」と読み、音の大きく異なる（判定で落ちうる）語。"}, "sentence_index": null, "correct_answer": "読み書き"}, "level_3": {"options": [{"text": "読み書き", "is_correct": true, "explanation": "「読み書きのテスト」で、読み書きの力を測る試験になる。"}, {"text": "窓", "is_correct": false, "explanation": "「窓のテストに合格した」は意味が通らない。"}, {"text": "夕方", "is_correct": false, "explanation": "「夕方のテストに合格」はこの文脈で不自然。"}, {"text": "靴", "is_correct": false, "explanation": "「靴のテストに合格」は意味をなさない。"}], "explanations": {"読み書き": "「読み書きのテスト」で、読み書きの力を測る試験になる。", "窓": "「窓のテストに合格した」は意味が通らない。", "夕方": "「夕方のテストに合格」はこの文脈で不自然。", "靴": "「靴のテストに合格」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "読み書き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "読み書きが山を登った。", "explanation": "能力を動作の主体にしており誤り。"}, {"text": "読み書きを切って料理した。", "explanation": "食材のように扱っていて誤り。"}, {"text": "この服は読み書きが青い。", "explanation": "色の表現に使っており意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35133, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹は漢字の読み書きが速く走れる。", "corrected_sentence": "妹は漢字の読み書きができる。", "error_description": "能力を表す「読み書き」に「速く走れる」を続けており意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35133, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「仕事で」で場面を表し、「でも」で「仕事の場面でも」となる。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表し、「仕事をも大切だ」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、ここでは非文。"}, {"text": "が", "is_correct": false, "explanation": "主格を表すが「仕事がも」は非文。"}], "correct_answer": "で", "explanations": {"で": "「仕事で」で場面を表し、「でも」で「仕事の場面でも」となる。", "を": "目的語を表し、「仕事をも大切だ」は不自然。", "へ": "方向を表し、ここでは非文。", "が": "主格を表すが「仕事がも」は非文。"}, "error_tags": {"を": "object_marking", "へ": "direction", "が": "topic_vs_subject"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "広がる", "is_correct": true, "explanation": "正解。「ひろがる」と読む。"}, {"text": "転がる", "is_correct": false, "explanation": "「ころがる」と読み、最初の「ひ」が「こ」に変わった一モーラ違いの語。"}, {"text": "広げる", "is_correct": false, "explanation": "「ひろげる」と読み、「が」が「げ」に変わった一モーラ違いの語。"}, {"text": "拾える", "is_correct": false, "explanation": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}], "explanations": {"広がる": "正解。「ひろがる」と読む。", "転がる": "「ころがる」と読み、最初の「ひ」が「こ」に変わった一モーラ違いの語。", "広げる": "「ひろげる」と読み、「が」が「げ」に変わった一モーラ違いの語。", "拾える": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "広がる"}, "level_3": {"options": [{"text": "広がった", "is_correct": true, "explanation": "火が山全体にうつっていく様子を表す。"}, {"text": "座った", "is_correct": false, "explanation": "火は座らないので意味が通らない。"}, {"text": "読んだ", "is_correct": false, "explanation": "火が読むことはない。"}, {"text": "答えた", "is_correct": false, "explanation": "火が答えることはなく不自然。"}], "explanations": {"広がった": "火が山全体にうつっていく様子を表す。", "座った": "火は座らないので意味が通らない。", "読んだ": "火が読むことはない。", "答えた": "火が答えることはなく不自然。"}, "sentence_index": 0, "correct_answer": "広がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は弟にお菓子を広がった。", "explanation": "人に物を与える意味のように使っており誤り。"}, {"text": "広がる先生が教室に来た。", "explanation": "人の性質のように使っていて意味が通らない。"}, {"text": "彼は本を広がった。", "explanation": "自動詞に「を」を付けており誤り。広げるが正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "水が床を広がった。", "corrected_sentence": "水が床に広がった。", "error_description": "広がる場所は「に」で表す。「を広がる」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広がって", "is_correct": true, "explanation": "「いる」に続くて形で、雲が広がった状態を表す。"}, {"text": "広がる", "is_correct": false, "explanation": "辞書形で、「いる」に直接続かない。"}, {"text": "広がった", "is_correct": false, "explanation": "た形で、「いる」に続かない。"}, {"text": "広がれば", "is_correct": false, "explanation": "条件形で、「いる」に続かない。"}], "correct_form": "広がって", "base_form": "広がる", "form_label": "て形（ている）", "sentence_index": 1, "explanations": {"広がって": "「いる」に続くて形で、雲が広がった状態を表す。", "広がる": "辞書形で、「いる」に直接続かない。", "広がった": "た形で、「いる」に続かない。", "広がれば": "条件形で、「いる」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「広がる」の主語「雲」を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表し、自動詞と合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所を表し、「雲で広がって」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「広がる」の主語「雲」を表す。", "を": "目的語を表し、自動詞と合わない。", "で": "手段・場所を表し、「雲で広がって」は不自然。", "へ": "方向を表し、主語を示せない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "へ": "direction"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮む", "is_correct": true, "explanation": "小さくなることを表し、「広がる」の反対。"}, {"text": "伸びる", "is_correct": false, "explanation": "大きくなる方向の意味で、反対ではない。"}, {"text": "流れる", "is_correct": false, "explanation": "水などが動くことで、反対ではない。"}, {"text": "読む", "is_correct": false, "explanation": "本を読む動作で、関係がない。"}], "correct_answer": "縮む", "explanations": {"縮む": "小さくなることを表し、「広がる」の反対。", "伸びる": "大きくなる方向の意味で、反対ではない。", "流れる": "水などが動くことで、反対ではない。", "読む": "本を読む動作で、関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "広がる", "is_correct": true, "explanation": "正解。「ひろがる」と読む。"}, {"text": "広める", "is_correct": false, "explanation": "「ひろめる」と読み、「が」が「め」に変わった一モーラ違いの語。"}, {"text": "拾える", "is_correct": false, "explanation": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}, {"text": "広まる", "is_correct": false, "explanation": "「ひろまる」と読み、「が」が「ま」に変わった一モーラ違いの。物理的な広がりには使わない語。"}], "explanations": {"広がる": "正解。「ひろがる」と読む。", "広める": "「ひろめる」と読み、「が」が「め」に変わった一モーラ違いの語。", "拾える": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。", "広まる": "「ひろまる」と読み、「が」が「ま」に変わった一モーラ違いの。物理的な広がりには使わない語。"}, "sentence_index": null, "correct_answer": "広がる"}, "level_3": {"options": [{"text": "広がらない", "is_correct": true, "explanation": "紙の上でインクがにじまない様子を表す。"}, {"text": "歩かない", "is_correct": false, "explanation": "インクは歩かないので意味が通らない。"}, {"text": "話さない", "is_correct": false, "explanation": "インクが話すことはない。"}, {"text": "笑わない", "is_correct": false, "explanation": "インクが笑うことはなく不自然。"}], "explanations": {"広がらない": "紙の上でインクがにじまない様子を表す。", "歩かない": "インクは歩かないので意味が通らない。", "話さない": "インクが話すことはない。", "笑わない": "インクが笑うことはなく不自然。"}, "sentence_index": 6, "correct_answer": "広がらない"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母はテーブルにお皿を広がった。", "explanation": "他動詞のように使っており誤り。"}, {"text": "広がる犬がほえている。", "explanation": "犬の性質のように使っていて意味が通らない。"}, {"text": "この時計はとても広がる。", "explanation": "時計の性能のように使っており誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煙が部屋を広がった。", "corrected_sentence": "煙が部屋に広がった。", "error_description": "広がる範囲は「に」で表す。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広がる", "is_correct": true, "explanation": "文末の現在の形で、においが庭に広がることを表す。"}, {"text": "広がら", "is_correct": false, "explanation": "未然形で、「ない」などが続かないと文を終えられない。"}, {"text": "広がり", "is_correct": false, "explanation": "連用形で、文を終えられない。"}, {"text": "広がれば", "is_correct": false, "explanation": "条件形で、文を終えられない。"}], "correct_form": "広がる", "base_form": "広がる", "form_label": "辞書形", "sentence_index": 7, "explanations": {"広がる": "文末の現在の形で、においが庭に広がることを表す。", "広がら": "未然形で、「ない」などが続かないと文を終えられない。", "広がり": "連用形で、文を終えられない。", "広がれば": "条件形で、文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35144, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "においが広がる先の場所「庭」を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表し、自動詞「広がる」と合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を表し、ここでは非文。"}, {"text": "の", "is_correct": false, "explanation": "名詞修飾の助詞で、「庭の広がる」は非文。"}], "correct_answer": "に", "explanations": {"に": "においが広がる先の場所「庭」を表す。", "を": "目的語を表し、自動詞「広がる」と合わない。", "と": "相手・並列を表し、ここでは非文。", "の": "名詞修飾の助詞で、「庭の広がる」は非文。"}, "error_tags": {"を": "object_marking", "と": "listing", "の": "other"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮まる", "is_correct": true, "explanation": "小さくなることを表し、「広がる」の反対。"}, {"text": "増える", "is_correct": false, "explanation": "量が多くなる意味で、反対ではない。"}, {"text": "膨らむ", "is_correct": false, "explanation": "大きくなる意味で、反対ではない。"}, {"text": "聞く", "is_correct": false, "explanation": "音を聞く動作で、関係がない。"}], "correct_answer": "縮まる", "explanations": {"縮まる": "小さくなることを表し、「広がる」の反対。", "増える": "量が多くなる意味で、反対ではない。", "膨らむ": "大きくなる意味で、反対ではない。", "聞く": "音を聞く動作で、関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "広がる", "is_correct": true, "explanation": "正解。「ひろがる」と読む。"}, {"text": "転がる", "is_correct": false, "explanation": "「ころがる」と読み、最初の「ひ」が「こ」に変わった一モーラ違いの語。"}, {"text": "広げる", "is_correct": false, "explanation": "「ひろげる」と読み、「が」が「げ」に変わった一モーラ違いの語。"}, {"text": "拾える", "is_correct": false, "explanation": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}], "explanations": {"広がる": "正解。「ひろがる」と読む。", "転がる": "「ころがる」と読み、最初の「ひ」が「こ」に変わった一モーラ違いの語。", "広げる": "「ひろげる」と読み、「が」が「げ」に変わった一モーラ違いの語。", "拾える": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "広がる"}, "level_3": {"options": [{"text": "広がった", "is_correct": true, "explanation": "うわさが学校中に伝わっていく様子を表す。"}, {"text": "座った", "is_correct": false, "explanation": "うわさは座らないので意味が通らない。"}, {"text": "泳いだ", "is_correct": false, "explanation": "うわさが泳ぐことはなく不自然。"}, {"text": "食べた", "is_correct": false, "explanation": "うわさが食べることはない。"}], "explanations": {"広がった": "うわさが学校中に伝わっていく様子を表す。", "座った": "うわさは座らないので意味が通らない。", "泳いだ": "うわさが泳ぐことはなく不自然。", "食べた": "うわさが食べることはない。"}, "sentence_index": 0, "correct_answer": "広がった"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は駅で友だちに広がった。", "explanation": "人が人に「広がる」という使い方は誤り。"}, {"text": "彼はご飯を広がった。", "explanation": "自動詞「広がる」に目的語「を」を付けており誤り。"}, {"text": "この鉛筆は広がるほど短い。", "explanation": "性質の形容に使っており意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "うわさが町中を広がった。", "corrected_sentence": "うわさが町中に広がった。", "error_description": "「広がる」は自動詞で、範囲は「に」で表す。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "広がって", "is_correct": true, "explanation": "「ている」に続くて形で、今広がりつつあることを表す。"}, {"text": "広がった", "is_correct": false, "explanation": "た形で、「いる」に続かない。"}, {"text": "広がる", "is_correct": false, "explanation": "辞書形で、「いる」に直接続かない。"}, {"text": "広がらない", "is_correct": false, "explanation": "否定形で、「いる」に続かない。"}], "correct_form": "広がって", "base_form": "広がる", "form_label": "て形（ている）", "sentence_index": 1, "explanations": {"広がって": "「ている」に続くて形で、今広がりつつあることを表す。", "広がった": "た形で、「いる」に続かない。", "広がる": "辞書形で、「いる」に直接続かない。", "広がらない": "否定形で、「いる」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「ネットで」で、話題が広がる場所・手段を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表し、この位置では非文。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手を表し、「ネットと話題が広がっている」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "主格を表し、「ネットが話題が」は非文。"}], "correct_answer": "で", "explanations": {"で": "「ネットで」で、話題が広がる場所・手段を表す。", "を": "目的語を表し、この位置では非文。", "と": "並列・相手を表し、「ネットと話題が広がっている」は不自然。", "が": "主格を表し、「ネットが話題が」は非文。"}, "error_tags": {"を": "object_marking", "と": "listing", "が": "topic_vs_subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭まる", "is_correct": true, "explanation": "範囲が小さくなることを表し、「広がる」の反対。"}, {"text": "増える", "is_correct": false, "explanation": "範囲が大きくなる意味に近く、反対ではない。"}, {"text": "伸びる", "is_correct": false, "explanation": "広がる方向の意味を持ち、反対ではない。"}, {"text": "歌う", "is_correct": false, "explanation": "声を出す動作で、範囲の大小と関係ない。"}], "correct_answer": "狭まる", "explanations": {"狭まる": "範囲が小さくなることを表し、「広がる」の反対。", "増える": "範囲が大きくなる意味に近く、反対ではない。", "伸びる": "広がる方向の意味を持ち、反対ではない。", "歌う": "声を出す動作で、範囲の大小と関係ない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "広がる", "is_correct": true, "explanation": "正解。「ひろがる」と読む。"}, {"text": "広める", "is_correct": false, "explanation": "「ひろめる」と読み、「が」が「め」に変わった一モーラ違いの語。"}, {"text": "拾える", "is_correct": false, "explanation": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。"}, {"text": "群がる", "is_correct": false, "explanation": "「むらがる」と読み、「ひろ」が「むら」に変わった（二モーラ違いで判定で落ちうる）語。"}], "explanations": {"広がる": "正解。「ひろがる」と読む。", "広める": "「ひろめる」と読み、「が」が「め」に変わった一モーラ違いの語。", "拾える": "「ひろえる」と読み、「が」が「え」に変わった一モーラ違いの語。", "群がる": "「むらがる」と読み、「ひろ」が「むら」に変わった（二モーラ違いで判定で落ちうる）語。"}, "sentence_index": null, "correct_answer": "広がる"}, "level_3": {"options": [{"text": "広がる", "is_correct": true, "explanation": "どんどん大きくなる人気を表し、名詞「人気」を修飾できる。"}, {"text": "眠る", "is_correct": false, "explanation": "「眠る人気」は意味が通らない。"}, {"text": "溶ける", "is_correct": false, "explanation": "人気が溶けることはなく、意味が通らない。"}, {"text": "沈む", "is_correct": false, "explanation": "「沈む人気」に店が驚くは文意に合わない。"}], "explanations": {"広がる": "どんどん大きくなる人気を表し、名詞「人気」を修飾できる。", "眠る": "「眠る人気」は意味が通らない。", "溶ける": "人気が溶けることはなく、意味が通らない。", "沈む": "「沈む人気」に店が驚くは文意に合わない。"}, "sentence_index": 6, "correct_answer": "広がる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私はかばんを広がった。", "explanation": "自動詞を他動詞のように使っており誤り。広げるが正しい。"}, {"text": "広がる先生にあいさつした。", "explanation": "人を修飾して性質のように使っており誤り。"}, {"text": "ペンが机の上で広がって寝ている。", "explanation": "物が寝るという意味不明な使い方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その歌は若者の間を広がった。", "corrected_sentence": "その歌は若者の間に広がった。", "error_description": "範囲を表すのは「に」で、「を広がる」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "広がらない", "is_correct": true, "explanation": "「なかなか」は否定と呼応するので否定形が正しい。"}, {"text": "広がる", "is_correct": false, "explanation": "肯定形で、「なかなか」と合わない。"}, {"text": "広がった", "is_correct": false, "explanation": "肯定の過去形で、「なかなか」と合わない。"}, {"text": "広がって", "is_correct": false, "explanation": "て形で、文を終えられない。"}], "correct_form": "広がらない", "base_form": "広がる", "form_label": "否定形（ない形）", "sentence_index": 7, "explanations": {"広がらない": "「なかなか」は否定と呼応するので否定形が正しい。", "広がる": "肯定形で、「なかなか」と合わない。", "広がった": "肯定の過去形で、「なかなか」と合わない。", "広がって": "て形で、文を終えられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35145, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "広がる先の範囲「学校中」を表す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を表し、自動詞「広がる」と合わない。"}, {"text": "が", "is_correct": false, "explanation": "主格を表し、「うわさは学校中が広がった」は非文。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を表し、ここでは非文。"}], "correct_answer": "に", "explanations": {"に": "広がる先の範囲「学校中」を表す。", "を": "目的語を表し、自動詞「広がる」と合わない。", "が": "主格を表し、「うわさは学校中が広がった」は非文。", "と": "相手・並列を表し、ここでは非文。"}, "error_tags": {"を": "object_marking", "が": "topic_vs_subject", "と": "listing"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "縮まる", "is_correct": true, "explanation": "差や範囲が小さくなることで、「広がる」の反対。"}, {"text": "広まる", "is_correct": false, "explanation": "伝わって大きくなる意味で、反対ではない。"}, {"text": "大きくなる", "is_correct": false, "explanation": "「広がる」に近い意味で、反対ではない。"}, {"text": "書く", "is_correct": false, "explanation": "文字を書く動作で、範囲の大小と関係ない。"}], "correct_answer": "縮まる", "explanations": {"縮まる": "差や範囲が小さくなることで、「広がる」の反対。", "広まる": "伝わって大きくなる意味で、反対ではない。", "大きくなる": "「広がる」に近い意味で、反対ではない。", "書く": "文字を書く動作で、範囲の大小と関係ない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35156, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通ずる", "is_correct": true, "explanation": "正解。「つうずる」と読む。"}, {"text": "封ずる", "is_correct": false, "explanation": "「ふうずる」と読み、最初の「つ」が「ふ」に変わった一モーラ違いの語。"}, {"text": "講ずる", "is_correct": false, "explanation": "「こうずる」と読み、最初の「つ」が「こ」に変わった一モーラ違いの語。"}, {"text": "投ずる", "is_correct": false, "explanation": "「とうずる」と読み、最初の「つ」が「と」に変わった一モーラ違いの語。"}, {"text": "報ずる", "is_correct": false, "explanation": "「ほうずる」と読み、最初の「つ」が「ほ」に変わった一モーラ違いの語。"}], "explanations": {"通ずる": "正解。「つうずる」と読む。", "封ずる": "「ふうずる」と読み、最初の「つ」が「ふ」に変わった一モーラ違いの語。", "講ずる": "「こうずる」と読み、最初の「つ」が「こ」に変わった一モーラ違いの語。", "投ずる": "「とうずる」と読み、最初の「つ」が「と」に変わった一モーラ違いの語。", "報ずる": "「ほうずる」と読み、最初の「つ」が「ほ」に変わった一モーラ違いの語。"}, "sentence_index": null, "correct_answer": "通ずる"}, "level_3": {"options": [{"text": "通ずる", "is_correct": true, "explanation": "道が駅までつながっていることを表す。"}, {"text": "眠る", "is_correct": false, "explanation": "道は眠らないので意味が通らない。"}, {"text": "笑う", "is_correct": false, "explanation": "道が笑うことはなく不自然。"}, {"text": "食べる", "is_correct": false, "explanation": "道が食べることはない。"}], "explanations": {"通ずる": "道が駅までつながっていることを表す。", "眠る": "道は眠らないので意味が通らない。", "笑う": "道が笑うことはなく不自然。", "食べる": "道が食べることはない。"}, "sentence_index": 0, "correct_answer": "通ずる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私はりんごを通ずる。", "explanation": "目的語「を」を取る他動詞のように使っており誤り。"}, {"text": "通ずる猫が庭で寝ている。", "explanation": "猫の性質のように使っており意味が通らない。"}, {"text": "この料理はとても通ずる。", "explanation": "味の形容に使っており誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d9db8cb-9e51-4b82-8bb5-cdd2c21f1e7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
