INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35174, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こったり、何かをしたりするちょうどよいとき。", "primary_collocate": null, "pronunciation": "じき", "ipa": "dʑiki", "syllable_count": 2, "sentences": [{"text": "今は旅行に行く時期ではない。", "target_word": "時期", "complexity_tier": "T3", "furigana": "いま りょこう い じき", "sentence_source": "generated"}, {"text": "種をまく時期が来た。", "target_word": "時期", "complexity_tier": "T3", "furigana": "たね じき き", "sentence_source": "generated"}, {"text": "引っ越しの時期を決めた。", "target_word": "時期", "complexity_tier": "T3", "furigana": "ひ こ じき き", "sentence_source": "generated"}, {"text": "その時期を待っている。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき ま", "sentence_source": "generated"}, {"text": "発表の時期はまだ秘密だ。", "target_word": "時期", "complexity_tier": "T3", "furigana": "はっぴょう じき ひみつ", "sentence_source": "generated"}, {"text": "いい時期に店を開いた。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき みせ ひら", "sentence_source": "generated"}, {"text": "時期が悪くて、うまくいかなかった。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき わる", "sentence_source": "generated"}, {"text": "時期を見て、話してみよう。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき み はな", "sentence_source": "generated"}, {"text": "結婚する時期を考えている。", "target_word": "時期", "complexity_tier": "T3", "furigana": "けっこん じき かんが", "sentence_source": "generated"}, {"text": "時期をまちがえて、損をした。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき そん", "sentence_source": "generated"}], "morphological_forms": [{"form": "時期尚早", "label": "派生"}, {"form": "時期外れ", "label": "派生"}, {"form": "時期的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事をするのに合うとき", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1',