INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35175, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が行われたり、ある状態が続いたりする、ある長さの時間。", "primary_collocate": null, "pronunciation": "じき", "ipa": "dʑiki", "syllable_count": 2, "sentences": [{"text": "この時期は雨が多い。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき あめ おお", "sentence_source": "generated"}, {"text": "テストの時期は図書館が混む。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき としょかん こ", "sentence_source": "generated"}, {"text": "夏の時期だけ店を開く。", "target_word": "時期", "complexity_tier": "T3", "furigana": "なつ じき みせ ひら", "sentence_source": "generated"}, {"text": "つらい時期を友達と過ごした。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき ともだち す", "sentence_source": "generated"}, {"text": "毎年この時期に祭りがある。", "target_word": "時期", "complexity_tier": "T3", "furigana": "まいとし じき まつ", "sentence_source": "generated"}, {"text": "忙しい時期が終わった。", "target_word": "時期", "complexity_tier": "T3", "furigana": "いそが じき お", "sentence_source": "generated"}, {"text": "その時期、私は大阪に住んでいた。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき わたし おおさか す", "sentence_source": "generated"}, {"text": "寒い時期はかぜに気をつけて。", "target_word": "時期", "complexity_tier": "T3", "furigana": "さむ じき き", "sentence_source": "generated"}, {"text": "同じ時期に二人が入学した。", "target_word": "時期", "complexity_tier": "T3", "furigana": "おな じき ふたり にゅうがく", "sentence_source": "generated"}, {"text": "この時期のりんごはおいしい。", "target_word": "時期", "complexity_tier": "T3", "furigana": "じき", "sentence_source": "generated"}], "morphological_forms": [{"form": "時期的", "label": "派生"}, {"form": "同時期", "label": "派生"}, {"form": "一時期", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ある状態が続く時間の範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-co