INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35186, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々の生活のしかたや考え方、人々が作り出してきたもの。", "primary_collocate": null, "pronunciation": "ぶんか", "ipa": "bɯŋka", "syllable_count": 3, "sentences": [{"text": "日本の文化に興味がある。", "target_word": "文化", "complexity_tier": "T3", "furigana": "にほん ぶんか きょうみ", "sentence_source": "generated"}, {"text": "国によって文化がちがう。", "target_word": "文化", "complexity_tier": "T3", "furigana": "くに ぶんか", "sentence_source": "generated"}, {"text": "文化を学ぶのは楽しい。", "target_word": "文化", "complexity_tier": "T3", "furigana": "ぶんか まな たの", "sentence_source": "generated"}, {"text": "祖母は昔の文化をよく知っている。", "target_word": "文化", "complexity_tier": "T3", "furigana": "そぼ むかし ぶんか し", "sentence_source": "generated"}, {"text": "食べ物は文化の一つだ。", "target_word": "文化", "complexity_tier": "T3", "furigana": "た もの ぶんか ひと", "sentence_source": "generated"}, {"text": "この町には古い文化が残っている。", "target_word": "文化", "complexity_tier": "T3", "furigana": "まち ふる ぶんか のこ", "sentence_source": "generated"}, {"text": "ほかの国の文化を大切にしよう。", "target_word": "文化", "complexity_tier": "T3", "furigana": "くに ぶんか たいせつ", "sentence_source": "generated"}, {"text": "文化のちがいにおどろいた。", "target_word": "文化", "complexity_tier": "T3", "furigana": "ぶんか", "sentence_source": "generated"}, {"text": "若者の文化は変わり続けている。", "target_word": "文化", "complexity_tier": "T3", "furigana": "わかもの ぶんか か つづ", "sentence_source": "generated"}, {"text": "音楽で文化を伝える。", "target_word": "文化", "complexity_tier": "T3", "furigana": "おんがく ぶんか つた", "sentence_source": "generated"}], "morphological_forms": [{"form": "文化的", "label": "派生"}, {"form": "文化祭", "label": "派生"}, {"form": "異文化", "label": "派生"}, {"form": "文化財", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人々の生活や考え方の全体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1eb5622-78b7-4da3-b63b-7da486a2acdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
