INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35256, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事のいちばん大事なところ。", "primary_collocate": null, "pronunciation": "こんぽん", "ipa": "kompoɴ", "syllable_count": 4, "sentences": [{"text": "問題の根本を考えよう。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "けんかの根本は小さな誤解だった。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "根本から考え直してみよう。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "これが失敗の根本です。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "根本の原因を調べている。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "彼は根本をよく分かっていない。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "先生は根本を丁寧に説明した。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "根本の考えは変わらない。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "まず根本を理解することが大切だ。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}, {"text": "根本に戻って話を聞こう。", "target_word": "根本", "complexity_tier": "T3", "furigana": "こんぽん", "sentence_source": "generated"}], "morphological_forms": [{"form": "根本的", "label": "派生"}, {"form": "根本的に", "label": "派生"}, {"form": "根本原因", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物事のいちばん大事なところ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b0a78a-7a2c-4d8f-a