INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35266, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "あることの範囲や数を小さく決めること。", "primary_collocate": null, "pronunciation": "かぎる", "ipa": "kagiɾɯ", "syllable_count": 3, "sentences": [{"text": "参加者を十人に限る。", "target_word": "限る", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "時間が限られている。", "target_word": "限られ", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "応募は学生に限ります。", "target_word": "限ります", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "席の数を二十に限った。", "target_word": "限った", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "使える場所は図書館に限られる。", "target_word": "限られる", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "話す時間を五分に限ってください。", "target_word": "限って", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "先生は宿題の量を限った。", "target_word": "限った", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "入場を大人に限る店だ。", "target_word": "限る", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "予算が限られているので節約した。", "target_word": "限られ", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}, {"text": "部員の数を限るのは良くない。", "target_word": "限る", "complexity_tier": "T3", "furigana": "かぎ", "sentence_source": "generated"}], "morphological_forms": [{"form": "限った", "label": "活用"}, {"form": "限って", "label": "活用"}, {"form": "限らない", "label": "活用"}, {"form": "限られる", "label": "活用"}, {"form": "限り", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 範囲や数を一定の内に決める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed'