INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35300, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "書いたり言ったりする、まとまった言葉の集まりのこと。", "primary_collocate": null, "pronunciation": "ぶんしょう", "ipa": "bɯɴɕoː", "syllable_count": 4, "sentences": [{"text": "彼女の文章はとても読みやすい。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "毎日、短い文章を書いている。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "この文章の意味が分からない。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "文章を声に出して読んだ。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "先生が私の文章をほめてくれた。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "文章が長すぎて疲れた。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "きれいな文章を書きたい。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "その文章は心に残った。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "文章の最後に名前を書く。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}, {"text": "兄は文章を書くのが上手だ。", "target_word": "文章", "complexity_tier": "T3", "furigana": "ぶんしょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "文章力", "label": "派生"}, {"form": "文章題", "label": "派生"}, {"form": "文章表現", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | まとまった言葉で書かれたもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1