INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35256, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根本", "is_correct": true, "explanation": "正解：根本（こんぽん）"}, {"text": "梱包", "is_correct": false, "explanation": "梱包（こんぽう）：最後のモーラ「ん」が「う」に変わる"}, {"text": "原本", "is_correct": false, "explanation": "原本（げんぽん）：最初のモーラ「こ」が「げ」に変わる"}, {"text": "今晩", "is_correct": false, "explanation": "今晩（こんばん）：三つ目のモーラ「ぽ」が「ば」に変わる"}], "explanations": {"根本": "正解：根本（こんぽん）", "梱包": "梱包（こんぽう）：最後のモーラ「ん」が「う」に変わる", "原本": "原本（げんぽん）：最初のモーラ「こ」が「げ」に変わる", "今晩": "今晩（こんばん）：三つ目のモーラ「ぽ」が「ば」に変わる"}, "sentence_index": null, "correct_answer": "根本"}, "level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "この文脈に合う語"}, {"text": "天気", "is_correct": false, "explanation": "意味：問題の天気は考える対象にならない"}, {"text": "牛乳", "is_correct": false, "explanation": "意味：問題と牛乳は結びつかない"}, {"text": "おやつ", "is_correct": false, "explanation": "連語：「問題のおやつ」は不自然な結びつき"}], "explanations": {"根本": "この文脈に合う語", "天気": "意味：問題の天気は考える対象にならない", "牛乳": "意味：問題と牛乳は結びつかない", "おやつ": "連語：「問題のおやつ」は不自然な結びつき"}, "sentence_index": 0, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "これが失敗を根本です。", "explanation": "助詞の混同：名詞をつなぐには「の」が必要"}, {"text": "一冊の根本を見つけた。", "explanation": "助数詞の誤り：抽象名詞の根本は「冊」で数えない"}, {"text": "根本ですこれが失敗の。", "explanation": "語順の誤り：主題—解説の構造が壊れている"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dacc54a2-fa56-4270-a9c3-a6cef6bd7b78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
