INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35266, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "限る", "is_correct": true, "explanation": "正解：限る（かぎる）"}, {"text": "飾る", "is_correct": false, "explanation": "飾る（かざる）：二拍目「ぎ」が「ざ」になる"}, {"text": "かじる", "is_correct": false, "explanation": "かじる（かじる）：二拍目「ぎ」が「じ」になる"}, {"text": "変える", "is_correct": false, "explanation": "変える（かえる）：二拍目「ぎ」が「え」になる"}, {"text": "掛かる", "is_correct": false, "explanation": "掛かる（かかる）：二拍目「ぎ」が「か」になる"}], "explanations": {"限る": "正解：限る（かぎる）", "飾る": "飾る（かざる）：二拍目「ぎ」が「ざ」になる", "かじる": "かじる（かじる）：二拍目「ぎ」が「じ」になる", "変える": "変える（かえる）：二拍目「ぎ」が「え」になる", "掛かる": "掛かる（かかる）：二拍目「ぎ」が「か」になる"}, "sentence_index": null, "correct_answer": "限る"}, "level_3": {"options": [{"text": "限る", "is_correct": true, "explanation": "この文脈に合う語"}, {"text": "走る", "is_correct": false, "explanation": "意味：参加者を十人に走るとは言えない"}, {"text": "食べる", "is_correct": false, "explanation": "意味：人数に対して食べるは使えない"}, {"text": "笑う", "is_correct": false, "explanation": "項構造：「〜を〜に笑う」という格の取り方はしない"}], "explanations": {"限る": "この文脈に合う語", "走る": "意味：参加者を十人に走るとは言えない", "食べる": "意味：人数に対して食べるは使えない", "笑う": "項構造：「〜を〜に笑う」という格の取り方はしない"}, "sentence_index": 0, "correct_answer": "限る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "席の数が二十を限った。", "explanation": "助詞の混同：限る対象は「を」、範囲は「に」"}, {"text": "席の数を二十に限らった。", "explanation": "活用の誤り：過去形は「限った」"}, {"text": "席の数を二十に限るだった。", "explanation": "活用の誤り：「限った」が正しい"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dacc54a2-fa56-4270-a9c3-a6cef6bd7b78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
