INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35367, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "知識や理論を体系的に研究する活動。また、その分野。", "primary_collocate": null, "pronunciation": "がくもん", "ipa": "gakɯmoɴ", "syllable_count": 4, "sentences": [{"text": "歴史は大切な学問だ。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "新しい学問が生まれた。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "心理学という学問がある。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "この学問は百年の歴史がある。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "どの学問を学びたいですか。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "経済学は人気の学問だ。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "学問の分野は多い。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "数学は古い学問の一つだ。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "彼は二つの学問を研究している。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}, {"text": "学問によって方法が違う。", "target_word": "学問", "complexity_tier": "T3", "furigana": "がくもん", "sentence_source": "generated"}], "morphological_forms": [{"form": "学問的", "label": "派生"}, {"form": "学問分野", "label": "派生"}, {"form": "学問の自由", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 体系的に研究する分野や活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '070d4aa8-f846-47e6-b