INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35312, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "急速", "is_correct": true, "explanation": "正解。「きゅうそく」と読む。"}, {"text": "給食", "is_correct": false, "explanation": "「きゅうしょく」は「そ」が「しょ」で、別の語。"}, {"text": "拘束", "is_correct": false, "explanation": "「こうそく」は「きゅう」が「こう」で、別の語。"}, {"text": "救国", "is_correct": false, "explanation": "「きゅうこく」は「そ」が「こ」で、別の語。"}, {"text": "規則", "is_correct": false, "explanation": "「きそく」は「きゅう」が「き」で、別の語。"}], "explanations": {"急速": "正解。「きゅうそく」と読む。", "給食": "「きゅうしょく」は「そ」が「しょ」で、別の語。", "拘束": "「こうそく」は「きゅう」が「こう」で、別の語。", "救国": "「きゅうこく」は「そ」が「こ」で、別の語。", "規則": "「きそく」は「きゅう」が「き」で、別の語。"}, "sentence_index": null, "correct_answer": "急速"}, "level_3": {"options": [{"text": "急速", "is_correct": true, "explanation": "町が大きくなる速さを表し、「急速に」で自然。"}, {"text": "正確", "is_correct": false, "explanation": "「正確に大きくなる」は意味が合わない。"}, {"text": "静か", "is_correct": false, "explanation": "「静かに大きくなった」は不自然。"}, {"text": "丁寧", "is_correct": false, "explanation": "「丁寧に大きくなる」とは言わない。"}], "explanations": {"急速": "町が大きくなる速さを表し、「急速に」で自然。", "正確": "「正確に大きくなる」は意味が合わない。", "静か": "「静かに大きくなった」は不自然。", "丁寧": "「丁寧に大きくなる」とは言わない。"}, "sentence_index": 0, "correct_answer": "急速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "急速な友だちと遊んだ。", "explanation": "「急速」は人の性質には使わない。"}, {"text": "このかばんは急速だ。", "explanation": "物そのものの性質ではなく、変化の速さに使う。"}, {"text": "急速に座ってください。", "explanation": "動作の指示にはふつう「急いで」「すぐに」を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe69e4a-f2d4-4e53-81e8-f492086e6a10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35312, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は急速に走って駅へ行った。", "corrected_sentence": "彼は急いで走って駅へ行った。", "error_description": "「急速」は変化や進み方の速さに使い、人が急ぐ動作には「急いで」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "急速", "is_correct": true, "explanation": "後ろの「に」と合わせて「急速に」となり、動詞「上達した」を修飾する。"}, {"text": "急速な", "is_correct": false, "explanation": "「急速なに」となり、連体形と「に」が重なって非文。"}, {"text": "急速だ", "is_correct": false, "explanation": "終止形で、後ろに「に」は続かない。"}, {"text": "急速だった", "is_correct": false, "explanation": "過去の終止形で、「に」と続けられない。"}], "correct_form": "急速", "base_form": "急速", "form_label": "語幹（連用形「に」の前）", "sentence_index": 1, "explanations": {"急速": "後ろの「に」と合わせて「急速に」となり、動詞「上達した」を修飾する。", "急速な": "「急速なに」となり、連体形と「に」が重なって非文。", "急速だ": "終止形で、後ろに「に」は続かない。", "急速だった": "過去の終止形で、「に」と続けられない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe69e4a-f2d4-4e53-81e8-f492086e6a10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
