INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35322, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上昇", "is_correct": true, "explanation": "正解。「じょうしょう」と読む。"}, {"text": "交渉", "is_correct": false, "explanation": "「こうしょう」は「じょう」が「こう」で、別の語。"}, {"text": "上々", "is_correct": false, "explanation": "「じょうじょう」は「しょう」が「じょう」で、別の語。"}, {"text": "少々", "is_correct": false, "explanation": "「しょうしょう」は「じょう」が「しょう」で、別の語。"}, {"text": "嘲笑", "is_correct": false, "explanation": "「ちょうしょう」は「じょう」が「ちょう」で、別の語。"}], "explanations": {"上昇": "正解。「じょうしょう」と読む。", "交渉": "「こうしょう」は「じょう」が「こう」で、別の語。", "上々": "「じょうじょう」は「しょう」が「じょう」で、別の語。", "少々": "「しょうしょう」は「じょう」が「しょう」で、別の語。", "嘲笑": "「ちょうしょう」は「じょう」が「ちょう」で、別の語。"}, "sentence_index": null, "correct_answer": "上昇"}, "level_3": {"options": [{"text": "上昇", "is_correct": true, "explanation": "気温が高くなることで、「気温の上昇」は自然。"}, {"text": "出発", "is_correct": false, "explanation": "気温は出発しない。"}, {"text": "到着", "is_correct": false, "explanation": "気温に到着は使わない。"}, {"text": "参加", "is_correct": false, "explanation": "気温が参加することはない。"}], "explanations": {"上昇": "気温が高くなることで、「気温の上昇」は自然。", "出発": "気温は出発しない。", "到着": "気温に到着は使わない。", "参加": "気温が参加することはない。"}, "sentence_index": 0, "correct_answer": "上昇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の性格は上昇だ。", "explanation": "「上昇」は性格を表さない。"}, {"text": "階段を上昇して部屋に入った。", "explanation": "人が階段を上がる動作には「上る」を使う。"}, {"text": "上昇な本を読んだ。", "explanation": "「上昇」は形容詞のように「な」で使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe69e4a-f2d4-4e53-81e8-f492086e6a10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_ba