INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35322, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「物価」が上昇する主語なので「が」。"}, {"text": "を", "is_correct": false, "explanation": "「上昇する」は自動詞で、目的語の「を」をとらない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を表し、主語を示せない。"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、ここでは主語にならない。"}], "correct_answer": "が", "explanations": {"が": "「物価」が上昇する主語なので「が」。", "を": "「上昇する」は自動詞で、目的語の「を」をとらない。", "で": "手段や場所を表し、主語を示せない。", "に": "着点を表し、ここでは主語にならない。"}, "error_tags": {"を": "object_marking", "で": "instrument", "に": "location_vs_target"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "低くなることで、「上昇」の反対。"}, {"text": "増加", "is_correct": false, "explanation": "増えることで、反対ではない。"}, {"text": "向上", "is_correct": false, "explanation": "よくなることで、類義に近い。"}, {"text": "発展", "is_correct": false, "explanation": "広がり伸びることで、反対ではない。"}], "correct_answer": "下降", "explanations": {"下降": "低くなることで、「上昇」の反対。", "増加": "増えることで、反対ではない。", "向上": "よくなることで、類義に近い。", "発展": "広がり伸びることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe69e4a-f2d4-4e53-81e8-f492086e6a10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
