INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35387, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのものを一つにまとめること。また、まとまること。", "primary_collocate": null, "pronunciation": "とういつ", "ipa": "toːitsɯ", "syllable_count": 4, "sentences": [{"text": "書き方を統一してください。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "部屋の色を白で統一した。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "デザインの統一が大切だ。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "形式を統一すると読みやすい。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "統一されたルールで試合をする。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "服装の統一を決めた。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "表記の統一ができていない。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "三つの会社が統一された。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "統一感のある部屋が好きだ。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}, {"text": "名前の書き方を統一しよう。", "target_word": "統一", "complexity_tier": "T3", "furigana": "とういつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "統一する", "label": "派生"}, {"form": "統一して", "label": "派生"}, {"form": "統一感", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 複数を一つにまとめること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dae21c8-da