INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35402, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々が集まって、いっしょにくらす集まり。", "primary_collocate": null, "pronunciation": "しゃかい", "ipa": "ɕakai", "syllable_count": 3, "sentences": [{"text": "社会のルールを守ろう。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会に出て働きたい。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "今の社会は便利になった。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会の役に立つ人になりたい。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "彼は社会で活躍している。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会は人々でできている。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会の変化はとても速い。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "よい社会を作りたい。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会について学んでいる。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}, {"text": "社会が少しずつ変わっている。", "target_word": "社会", "complexity_tier": "T3", "furigana": "しゃかい", "sentence_source": "generated"}], "morphological_forms": [{"form": "社会的", "label": "派生"}, {"form": "社会人", "label": "派生"}, {"form": "社会問題", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人々が共にくらす集まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dae21c8-da71-42ce-88c8-bd392aa7