INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35408, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や社会のきまりや、みんなのことを決める活動。", "primary_collocate": null, "pronunciation": "せいじ", "ipa": "seːdʑi", "syllable_count": 3, "sentences": [{"text": "政治に関心を持とう。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "父は政治の話が好きだ。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "政治は私たちの生活に関係する。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "若者も政治を考えている。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "政治が変わってほしい。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "この国の政治は安定している。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "政治について友達と話した。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "政治のニュースを毎日見る。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "彼は政治を学んでいる。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}, {"text": "よい政治が必要だ。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ", "sentence_source": "generated"}], "morphological_forms": [{"form": "政治家", "label": "派生"}, {"form": "政治的", "label": "派生"}, {"form": "政治学", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 国や社会のことを決める活動", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dae21c8-da71-42ce-88c8-bd392aa717d1')