INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35376, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寄与", "is_correct": true, "explanation": "正解。読みは「きよ」。"}, {"text": "記事", "is_correct": false, "explanation": "読みは「きじ」。「よ」が「じ」の一モーラ差。"}, {"text": "傷", "is_correct": false, "explanation": "読みは「きず」。「よ」が「ず」の一モーラ差。"}, {"text": "霧", "is_correct": false, "explanation": "読みは「きり」。「よ」が「り」の一モーラ差。"}, {"text": "規模", "is_correct": false, "explanation": "読みは「きぼ」。「よ」が「ぼ」の一モーラ差。"}], "explanations": {"寄与": "正解。読みは「きよ」。", "記事": "読みは「きじ」。「よ」が「じ」の一モーラ差。", "傷": "読みは「きず」。「よ」が「ず」の一モーラ差。", "霧": "読みは「きり」。「よ」が「り」の一モーラ差。", "規模": "読みは「きぼ」。「よ」が「ぼ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "寄与"}, "level_3": {"options": [{"text": "寄与", "is_correct": true, "explanation": "町の発展を助けたという意味で自然。"}, {"text": "到着", "is_correct": false, "explanation": "意味：「発展に到着する」とは言わない。"}, {"text": "睡眠", "is_correct": false, "explanation": "意味：「発展に睡眠する」は意味が通らない。"}, {"text": "食事", "is_correct": false, "explanation": "意味：「発展に食事する」は意味が通らない。"}], "explanations": {"寄与": "町の発展を助けたという意味で自然。", "到着": "意味：「発展に到着する」とは言わない。", "睡眠": "意味：「発展に睡眠する」は意味が通らない。", "食事": "意味：「発展に食事する」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "寄与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寄与のせいで地域がだめになった。", "explanation": "語義の誤り：寄与はよい結果を助けることで、悪い結果の原因には使わない。"}, {"text": "一冊の寄与をもらった。", "explanation": "助数詞の誤り：寄与は物ではなく数えられない。"}, {"text": "地域を寄与する仕事がしたい。", "explanation": "助詞の混同：寄与の対象は「に」で示す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245f6d46-5019-4d80-8723-ada9a5b4ddd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
