INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35376, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「寄与する」の対象（助ける先）を示す。"}, {"text": "を", "is_correct": false, "explanation": "「寄与する」は「を」で対象をとらない。"}, {"text": "が", "is_correct": false, "explanation": "「治療が寄与している」は「この薬は」と並ばず非文。"}, {"text": "から", "is_correct": false, "explanation": "起点の「から」では助ける先を示せない。"}], "correct_answer": "に", "explanations": {"に": "「寄与する」の対象（助ける先）を示す。", "を": "「寄与する」は「を」で対象をとらない。", "が": "「治療が寄与している」は「この薬は」と並ばず非文。", "から": "起点の「から」では助ける先を示せない。"}, "error_tags": {"を": "object_marking", "が": "other", "から": "source_vs_goal"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245f6d46-5019-4d80-8723-ada9a5b4ddd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35376, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "寄与", "is_correct": true, "explanation": "正解。読みは「きよ」。"}, {"text": "岸", "is_correct": false, "explanation": "読みは「きし」。「よ」が「し」の一モーラ差。"}, {"text": "器具", "is_correct": false, "explanation": "読みは「きぐ」。「よ」が「ぐ」の一モーラ差。"}, {"text": "霧", "is_correct": false, "explanation": "読みは「きり」。「よ」が「り」の一モーラ差。"}, {"text": "記事", "is_correct": false, "explanation": "読みは「きじ」。「よ」が「じ」の一モーラ差。"}], "explanations": {"寄与": "正解。読みは「きよ」。", "岸": "読みは「きし」。「よ」が「し」の一モーラ差。", "器具": "読みは「きぐ」。「よ」が「ぐ」の一モーラ差。", "霧": "読みは「きり」。「よ」が「り」の一モーラ差。", "記事": "読みは「きじ」。「よ」が「じ」の一モーラ差。"}, "sentence_index": null, "correct_answer": "寄与"}, "level_3": {"options": [{"text": "寄与", "is_correct": true, "explanation": "助けた度合いの大きさを考える、で自然。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：「散歩の大きさ」とは言わない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：「天気の大きさ」とは言わない。"}, {"text": "昼寝", "is_correct": false, "explanation": "意味：「昼寝の大きさ」とは言わない。"}], "explanations": {"寄与": "助けた度合いの大きさを考える、で自然。", "散歩": "意味：「散歩の大きさ」とは言わない。", "天気": "意味：「天気の大きさ」とは言わない。", "昼寝": "意味：「昼寝の大きさ」とは言わない。"}, "sentence_index": 6, "correct_answer": "寄与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町への寄与で罰を受けた。", "explanation": "語義の誤り：寄与はよい行いで、罰の理由にならない。"}, {"text": "町への寄与を一枚書いた。", "explanation": "助数詞の誤り：寄与は紙のように数えない。"}, {"text": "町を寄与で表彰された。", "explanation": "助詞の混同：「町への寄与」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245f6d46-5019-4d80-8723-ada9a5b4ddd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
