INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35377, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "寄与", "is_correct": true, "explanation": "正解。読みは「きよ」。"}, {"text": "傷", "is_correct": false, "explanation": "読みは「きず」。「よ」が「ず」の一モーラ差。"}, {"text": "規模", "is_correct": false, "explanation": "読みは「きぼ」。「よ」が「ぼ」の一モーラ差。"}, {"text": "岸", "is_correct": false, "explanation": "読みは「きし」。「よ」が「し」の一モーラ差。"}, {"text": "木目", "is_correct": false, "explanation": "読みは「きめ」。「よ」が「め」の一モーラ差。"}], "explanations": {"寄与": "正解。読みは「きよ」。", "傷": "読みは「きず」。「よ」が「ず」の一モーラ差。", "規模": "読みは「きぼ」。「よ」が「ぼ」の一モーラ差。", "岸": "読みは「きし」。「よ」が「し」の一モーラ差。", "木目": "読みは「きめ」。「よ」が「め」の一モーラ差。"}, "sentence_index": null, "correct_answer": "寄与"}, "level_3": {"options": [{"text": "寄与", "is_correct": true, "explanation": "運動が健康という結果を助ける、で自然。"}, {"text": "留守", "is_correct": false, "explanation": "意味：「健康に留守する」とは言わない。"}, {"text": "散歩", "is_correct": false, "explanation": "項構造：「健康に散歩する」は意味が通らない。"}, {"text": "到着", "is_correct": false, "explanation": "意味：「健康に到着する」とは言わない。"}], "explanations": {"寄与": "運動が健康という結果を助ける、で自然。", "留守": "意味：「健康に留守する」とは言わない。", "散歩": "項構造：「健康に散歩する」は意味が通らない。", "到着": "意味：「健康に到着する」とは言わない。"}, "sentence_index": 0, "correct_answer": "寄与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その発見は科学への寄与で、科学を遅らせた。", "explanation": "語義の誤り：寄与は結果を進める助けで、遅らせることではない。"}, {"text": "その発見は科学への寄与を三本だ。", "explanation": "助数詞の誤り：寄与は「本」で数えない。"}, {"text": "その発見は科学から寄与だ。", "explanation": "助詞の混同：「科学への寄与」とすべき。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245f6d46-5019-4d80-8723-ada9a5b4ddd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
