INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35386, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「統一する」の目的語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「意見に統一したい」はまとめる対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「意見で統一したい」は手段の意味になり不自然。"}, {"text": "から", "is_correct": false, "explanation": "「意見から統一したい」は非文。"}], "correct_answer": "を", "explanations": {"を": "「統一する」の目的語を示す。", "に": "「意見に統一したい」はまとめる対象を示せない。", "で": "「意見で統一したい」は手段の意味になり不自然。", "から": "「意見から統一したい」は非文。"}, "error_tags": {"に": "location_vs_target", "で": "instrument", "から": "source_vs_goal"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分裂", "is_correct": true, "explanation": "ひとつのものが分かれることで、統一と反対。"}, {"text": "結合", "is_correct": false, "explanation": "結びついて一つになることで、対義ではない。"}, {"text": "改革", "is_correct": false, "explanation": "制度を変えることで、統一の対義ではない。"}, {"text": "成立", "is_correct": false, "explanation": "ものごとができあがることで、対義関係にない。"}], "correct_answer": "分裂", "explanations": {"分裂": "ひとつのものが分かれることで、統一と反対。", "結合": "結びついて一つになることで、対義ではない。", "改革": "制度を変えることで、統一の対義ではない。", "成立": "ものごとができあがることで、対義関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245f6d46-5019-4d80-8723-ada9a5b4ddd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
