INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35409, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国家の統治や政策、権力の獲得・行使など、社会全体の秩序や利害に関わる活動や分野。", "primary_collocate": null, "pronunciation": "せいじ", "ipa": "seːdʑi", "syllable_count": 3, "sentences": [{"text": "父は毎晩、政治のニュースを見ている。", "target_word": "政治", "complexity_tier": "T3", "furigana": "ちち まいばん せいじ", "sentence_source": "generated"}, {"text": "私は政治に興味を持っている。", "target_word": "政治", "complexity_tier": "T3", "furigana": "わたし せいじ きょうみ も", "sentence_source": "generated"}, {"text": "政治の話は少し難しい。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ はなし すこ むずか", "sentence_source": "generated"}, {"text": "若い人も政治について考えてほしい。", "target_word": "政治", "complexity_tier": "T3", "furigana": "わか ひと せいじ かんが", "sentence_source": "generated"}, {"text": "この国の政治は変わってきている。", "target_word": "政治", "complexity_tier": "T3", "furigana": "くに せいじ か", "sentence_source": "generated"}, {"text": "兄は大学で政治を勉強している。", "target_word": "政治", "complexity_tier": "T3", "furigana": "あに だいがく せいじ べんきょう", "sentence_source": "generated"}, {"text": "政治が変われば、生活も変わる。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せいじ か せいかつ か", "sentence_source": "generated"}, {"text": "友だちと政治の意見を話し合った。", "target_word": "政治", "complexity_tier": "T3", "furigana": "とも せいじ いけん はな あ", "sentence_source": "generated"}, {"text": "選挙の前は政治の話が多くなる。", "target_word": "政治", "complexity_tier": "T3", "furigana": "せんきょ まえ せいじ はなし おお", "sentence_source": "generated"}, {"text": "新聞で政治の記事を読んだ。", "target_word": "政治", "complexity_tier": "T3", "furigana": "しんぶん せいじ きじ よ", "sentence_source": "generated"}], "morphological_forms": [{"form": "政治家", "label": "派生"}, {"form": "政治的", "label": "派生"}, {"form": "政治学", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 国を治める活動や分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82ccba17-cff2-4fa7-99d2-f72748816a0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35420, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "知らない人に正しいことを教えて、よくわかるようにすること。", "primary_collocate": null, "pronunciation": "けいもう", "ipa": "keːmoː", "syllable_count": 4, "sentences": [{"text": "先生は子どもたちの啓蒙に力を入れている。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "せんせい こ けいもう ちから い", "sentence_source": "generated"}, {"text": "この本は人々の啓蒙のために書かれた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "ほん ひとびと けいもう か", "sentence_source": "generated"}, {"text": "ごみを減らすための啓蒙が大切だ。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "へ けいもう たいせつ", "sentence_source": "generated"}, {"text": "町では交通安全の啓蒙をしている。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "まち こうつうあんぜん けいもう", "sentence_source": "generated"}, {"text": "彼は病気について啓蒙を続けている。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "かれ びょうき けいもう つづ", "sentence_source": "generated"}, {"text": "啓蒙のおかげで、みんなが手を洗うようになった。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう て あら", "sentence_source": "generated"}, {"text": "ポスターは啓蒙の一つの方法だ。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう ひと ほうほう", "sentence_source": "generated"}, {"text": "学校で防災の啓蒙が行われた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "がっこう ぼうさい けいもう おこな", "sentence_source": "generated"}, {"text": "啓蒙は時間がかかる仕事だ。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう じかん しごと", "sentence_source": "generated"}, {"text": "医者が健康の啓蒙を進めている。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "いしゃ けんこう けいもう すす", "sentence_source": "generated"}], "morphological_forms": [{"form": "啓蒙する", "label": "派生"}, {"form": "啓蒙活動", "label": "派生"}, {"form": "啓蒙思想", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 知らない人に正しく教えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82ccba17-cff2-4fa7-99d2-f72748816a0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35421, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人々に知識や道理を教え、無知や偏見から解放して、正しい考え方へ導くこと。また、そのような活動や思想。", "primary_collocate": null, "pronunciation": "けいもう", "ipa": "keːmoː", "syllable_count": 4, "sentences": [{"text": "啓蒙の思想はヨーロッパで広がった。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう しそう ひろ", "sentence_source": "generated"}, {"text": "彼は人々の啓蒙に一生をささげた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "かれ ひとびと けいもう いっしょう", "sentence_source": "generated"}, {"text": "差別をなくすための啓蒙が必要だ。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "さべつ けいもう ひつよう", "sentence_source": "generated"}, {"text": "啓蒙によって、古い考えが変わった。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう ふる かんが か", "sentence_source": "generated"}, {"text": "その学者は啓蒙の大切さを説いた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "がくしゃ けいもう たいせつ と", "sentence_source": "generated"}, {"text": "この運動は社会の啓蒙を目指している。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "うんどう しゃかい けいもう めざ", "sentence_source": "generated"}, {"text": "啓蒙の時代に新しい考えが生まれた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "けいもう じだい あたら かんが う", "sentence_source": "generated"}, {"text": "新聞は市民の啓蒙に役立ってきた。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "しんぶん しみん けいもう やくだ", "sentence_source": "generated"}, {"text": "偏見をなくす啓蒙は簡単ではない。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "へんけん けいもう かんたん", "sentence_source": "generated"}, {"text": "彼女は女性の権利の啓蒙をしている。", "target_word": "啓蒙", "complexity_tier": "T3", "furigana": "かのじょ じょせい けんり けいもう", "sentence_source": "generated"}], "morphological_forms": [{"form": "啓蒙する", "label": "派生"}, {"form": "啓蒙活動", "label": "派生"}, {"form": "啓蒙思想", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 人々を無知から正しい考えへ導く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82ccba17-cff2-4fa7-99d2-f72748816a0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35409, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政治", "is_correct": true, "explanation": "正解：政治（せいじ）。"}, {"text": "静止", "is_correct": false, "explanation": "静止（せいし）：「じ」が「し」になる清濁の違い"}, {"text": "聖地", "is_correct": false, "explanation": "聖地（せいち）：「じ」が「ち」に変わる一モーラ違い"}, {"text": "星座", "is_correct": false, "explanation": "星座（せいざ）：「じ」が「ざ」に変わる一モーラ違い"}, {"text": "制度", "is_correct": false, "explanation": "制度（せいど）：「じ」が「ど」に変わる一モーラ違い"}, {"text": "製図", "is_correct": false, "explanation": "製図（せいず）：「じ」が「ず」に変わる一モーラ違い"}], "explanations": {"政治": "正解：政治（せいじ）。", "静止": "静止（せいし）：「じ」が「し」になる清濁の違い", "聖地": "聖地（せいち）：「じ」が「ち」に変わる一モーラ違い", "星座": "星座（せいざ）：「じ」が「ざ」に変わる一モーラ違い", "制度": "制度（せいど）：「じ」が「ど」に変わる一モーラ違い", "製図": "製図（せいず）：「じ」が「ず」に変わる一モーラ違い"}, "sentence_index": null, "correct_answer": "政治"}, "level_3": {"options": [{"text": "政治", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：鉛筆はニュースの話題として毎晩見るものではない。"}, {"text": "眠気", "is_correct": false, "explanation": "意味：眠気をニュースで見るのは不自然。"}, {"text": "毛布", "is_correct": false, "explanation": "連語：「毛布のニュース」は結びつきが不自然。"}], "explanations": {"政治": "文脈に合う正しい語。", "鉛筆": "意味：鉛筆はニュースの話題として毎晩見るものではない。", "眠気": "意味：眠気をニュースで見るのは不自然。", "毛布": "連語：「毛布のニュース」は結びつきが不自然。"}, "sentence_index": 0, "correct_answer": "政治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政治を一冊買ってきた。", "explanation": "助数詞の誤り：政治は本ではないので「一冊」で数えられない。"}, {"text": "政治で興味がある。", "explanation": "助詞の混同：興味の対象は「に」で示す。"}, {"text": "政治は明日たくさん食べた。", "explanation": "意味・アスペクトの誤り：政治は食べ物ではなく、明日と過去形も合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b270f44-82c8-4514-bc28-53a5d85a31c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35409, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は政治を興味を持っている。", "corrected_sentence": "私は政治に興味を持っている。", "error_description": "助詞の混同：興味の対象は「を」ではなく「に」で示す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b270f44-82c8-4514-bc28-53a5d85a31c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35409, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "この位置に必要な助詞。"}, {"text": "を", "is_correct": false, "explanation": "「を」は後の「興味を」と重なり、興味の対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所・手段を表し、興味の対象にならない。"}, {"text": "が", "is_correct": false, "explanation": "「政治が興味を持つ」となり主語が誤る。"}], "correct_answer": "に", "explanations": {"に": "この位置に必要な助詞。", "を": "「を」は後の「興味を」と重なり、興味の対象を示せない。", "で": "「で」は場所・手段を表し、興味の対象にならない。", "が": "「政治が興味を持つ」となり主語が誤る。"}, "error_tags": {"を": "object_marking", "で": "location_vs_target", "が": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b270f44-82c8-4514-bc28-53a5d85a31c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35409, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "政治", "is_correct": true, "explanation": "正解：政治（せいじ）。"}, {"text": "生死", "is_correct": false, "explanation": "生死（せいし）：「じ」が「し」になる清濁の違い"}, {"text": "戦時", "is_correct": false, "explanation": "戦時（せんじ）：「い」が「ん」に変わる一モーラ違い"}, {"text": "整地", "is_correct": false, "explanation": "整地（せいち）：「じ」が「ち」に変わる一モーラ違い"}, {"text": "正座", "is_correct": false, "explanation": "正座（せいざ）：「じ」が「ざ」に変わる一モーラ違い"}], "explanations": {"政治": "正解：政治（せいじ）。", "生死": "生死（せいし）：「じ」が「し」になる清濁の違い", "戦時": "戦時（せんじ）：「い」が「ん」に変わる一モーラ違い", "整地": "整地（せいち）：「じ」が「ち」に変わる一モーラ違い", "正座": "正座（せいざ）：「じ」が「ざ」に変わる一モーラ違い"}, "sentence_index": null, "correct_answer": "政治"}, "level_3": {"options": [{"text": "政治", "is_correct": true, "explanation": "文脈に合う正しい語。"}, {"text": "昨日", "is_correct": false, "explanation": "意味：昨日は過ぎた日なので変わることがない。"}, {"text": "円周率", "is_correct": false, "explanation": "意味：円周率は変わらない数で、生活とも結びつかない。"}, {"text": "誕生日", "is_correct": false, "explanation": "意味：誕生日は変えられるものではない。"}], "explanations": {"政治": "文脈に合う正しい語。", "昨日": "意味：昨日は過ぎた日なので変わることがない。", "円周率": "意味：円周率は変わらない数で、生活とも結びつかない。", "誕生日": "意味：誕生日は変えられるものではない。"}, "sentence_index": 6, "correct_answer": "政治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政治を三匹飼っている。", "explanation": "助数詞の誤り：政治は動物ではなく「匹」で数えない。"}, {"text": "政治が新聞を読んだ。", "explanation": "意味の誤り：政治は人ではないので新聞を読む主語にならない。"}, {"text": "政治の記事を明日読んだ。", "explanation": "時制の誤り：未来の「明日」と過去形「読んだ」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b270f44-82c8-4514-bc28-53a5d85a31c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.vali