INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35514, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たべものをつくるために、はたけや田んぼでしごとをすること。", "primary_collocate": null, "pronunciation": "のうぎょう", "ipa": "noːɡʲoː", "syllable_count": 4, "sentences": [{"text": "祖父は長い間、農業をしています。", "target_word": "農業", "complexity_tier": "T3", "furigana": "そふ なが あいだ のうぎょう", "sentence_source": "generated"}, {"text": "この村の人の多くは農業で生活している。", "target_word": "農業", "complexity_tier": "T3", "furigana": "むら ひと おお のうぎょう せいかつ", "sentence_source": "generated"}, {"text": "農業は天気にとても左右されます。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう てんき さゆう", "sentence_source": "generated"}, {"text": "兄は大学で農業を勉強しています。", "target_word": "農業", "complexity_tier": "T3", "furigana": "あに だいがく のうぎょう べんきょう", "sentence_source": "generated"}, {"text": "農業の仕事は朝がとても早いです。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう しごと あさ はや", "sentence_source": "generated"}, {"text": "最近、農業を始める若者が増えている。", "target_word": "農業", "complexity_tier": "T3", "furigana": "さいきん のうぎょう はじ わかもの ふ", "sentence_source": "generated"}, {"text": "この町は農業がさかんです。", "target_word": "農業", "complexity_tier": "T3", "furigana": "まち のうぎょう", "sentence_source": "generated"}, {"text": "農業に使う機械はとても高い。", "target_word": "農業", "complexity_tier": "T3", "furigana": "のうぎょう つか きかい たか", "sentence_source": "generated"}, {"text": "将来は農業の仕事がしたいです。", "target_word": "農業", "complexity_tier": "T3", "furigana": "しょうらい のうぎょう しごと", "sentence_source": "generated"}, {"text": "水がないと農業はできません。", "target_word": "農業", "complexity_tier": "T3", "furigana": "みず のうぎょう", "sentence_source": "generated"}], "morphological_forms": [{"form": "農業用", "label": "派生"}, {"form": "農業国", "label": "派生"}, {"form": "農業高校", "label": "派生"}], "register": "polite", "sense_fingerprint": "名詞 | 作物や家畜を育てる仕事", "collocate_grounding": {"statu