INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35528, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある決まった広さの土地や場所のこと。", "primary_collocate": null, "pronunciation": "ちいき", "ipa": "tɕiːki", "syllable_count": 3, "sentences": [{"text": "この地域は雪がたくさん降ります。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ゆき ふ", "sentence_source": "generated"}, {"text": "地域の人たちと公園を掃除した。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ひと こうえん そうじ", "sentence_source": "generated"}, {"text": "寒い地域では冬が長いです。", "target_word": "地域", "complexity_tier": "T3", "furigana": "さむ ちいき ふゆ なが", "sentence_source": "generated"}, {"text": "地域によって言葉が少し違う。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき ことば すこ ちが", "sentence_source": "generated"}, {"text": "私たちの地域にも新しい店ができた。", "target_word": "地域", "complexity_tier": "T3", "furigana": "わたし ちいき あたら みせ", "sentence_source": "generated"}, {"text": "この祭りは地域の大切な行事です。", "target_word": "地域", "complexity_tier": "T3", "furigana": "まつ ちいき たいせつ ぎょうじ", "sentence_source": "generated"}, {"text": "山の多い地域に住んでいます。", "target_word": "地域", "complexity_tier": "T3", "furigana": "やま おお ちいき す", "sentence_source": "generated"}, {"text": "地域で子どもを見守っている。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき こ みまも", "sentence_source": "generated"}, {"text": "その地域は昔から米で有名だ。", "target_word": "地域", "complexity_tier": "T3", "furigana": "ちいき むかし こめ ゆうめい", "sentence_source": "generated"}, {"text": "大雨で一部の地域が停電した。", "target_word": "地域", "complexity_tier": "T3", "furigana": "おおあめ いちぶ ちいき ていでん", "sentence_source": "generated"}], "morphological_forms": [{"form": "地域社会", "label": "派生"}, {"form": "地域的", "label": "派生"}, {"form": "地域差", "label": "派生"}], "register": "polite", "sense_fingerprint": "名詞 | 区切られたある範囲の土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate