INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35540, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みのった実や野菜などをとること。", "primary_collocate": null, "pronunciation": "しゅうかく", "ipa": "ɕɯːkakɯ", "syllable_count": 4, "sentences": [{"text": "庭のトマトの収穫を手伝った。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "にわ しゅうかく てつだ", "sentence_source": "generated"}, {"text": "秋はりんごの収穫の季節です。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "あき しゅうかく きせつ", "sentence_source": "generated"}, {"text": "みんなで畑のいもを収穫した。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "はたけ しゅうかく", "sentence_source": "generated"}, {"text": "収穫は朝早くから始まります。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく あさはや はじ", "sentence_source": "generated"}, {"text": "ぶどうの収穫は手で行います。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく て おこな", "sentence_source": "generated"}, {"text": "収穫したばかりの野菜はおいしい。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく やさい", "sentence_source": "generated"}, {"text": "子どもたちが収穫を楽しんでいる。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "こ しゅうかく たの", "sentence_source": "generated"}, {"text": "いちごを収穫する体験をした。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく たいけん", "sentence_source": "generated"}, {"text": "雨のせいで収穫が遅れた。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "あめ しゅうかく おく", "sentence_source": "generated"}, {"text": "収穫の日を家族で決めました。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく ひ かぞく き", "sentence_source": "generated"}], "morphological_forms": [{"form": "収穫する", "label": "派生"}, {"form": "収穫期", "label": "派生"}, {"form": "収穫祭", "label": "派生"}], "register": "polite", "sense_fingerprint": "名詞 | 実ったものを取ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'