INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35541, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "田畑で育てた農作物などを取り入れること。また、その量。", "primary_collocate": null, "pronunciation": "しゅうかく", "ipa": "ɕɯːkakɯ", "syllable_count": 4, "sentences": [{"text": "今年は米の収穫が多かった。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "ことし こめ しゅうかく おお", "sentence_source": "generated"}, {"text": "農家は秋に稲を収穫します。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "のうか あき いね しゅうかく", "sentence_source": "generated"}, {"text": "台風で麦の収穫が減ってしまった。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "たいふう むぎ しゅうかく へ", "sentence_source": "generated"}, {"text": "収穫の前に機械を準備する。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく まえ きかい じゅんび", "sentence_source": "generated"}, {"text": "収穫した米を倉庫に運んだ。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく こめ そうこ はこ", "sentence_source": "generated"}, {"text": "収穫は村全体の大きな仕事です。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく むらぜんたい おお しごと", "sentence_source": "generated"}, {"text": "天気がよくて収穫が順調だ。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "てんき しゅうかく じゅんちょう", "sentence_source": "generated"}, {"text": "この畑では年に二回収穫できる。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "はたけ ねん にかい しゅうかく", "sentence_source": "generated"}, {"text": "収穫が終わると祭りがあります。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "しゅうかく お まつ", "sentence_source": "generated"}, {"text": "小麦の収穫が去年より少ない。", "target_word": "収穫", "complexity_tier": "T3", "furigana": "こむぎ しゅうかく きょねん すく", "sentence_source": "generated"}], "morphological_forms": [{"form": "収穫する", "label": "派生"}, {"form": "収穫量", "label": "派生"}, {"form": "収穫高", "label": "派生"}], "register": "polite", "sense_fingerprint": "名詞 | 農作物を取り入れること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60dae0b3-051b-4867-b83a-2cda4d7bd406') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
