INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35514, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "農業", "is_correct": true, "explanation": "正解：「のうぎょう」と読む対象語。"}, {"text": "工業", "is_correct": false, "explanation": "「こうぎょう」と読む。第一モーラ「の」が「こ」に変わる一モーラ差。"}, {"text": "商業", "is_correct": false, "explanation": "「しょうぎょう」と読む。第一モーラ「の」が「しょ」に変わる一モーラ差。"}, {"text": "農協", "is_correct": false, "explanation": "「のうきょう」と読む。「ぎょ」と「きょ」の清濁の違い。"}, {"text": "同業", "is_correct": false, "explanation": "「どうぎょう」と読む。第一モーラ「の」が「ど」に変わる一モーラ差。"}], "explanations": {"農業": "正解：「のうぎょう」と読む対象語。", "工業": "「こうぎょう」と読む。第一モーラ「の」が「こ」に変わる一モーラ差。", "商業": "「しょうぎょう」と読む。第一モーラ「の」が「しょ」に変わる一モーラ差。", "農協": "「のうきょう」と読む。「ぎょ」と「きょ」の清濁の違い。", "同業": "「どうぎょう」と読む。第一モーラ「の」が「ど」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "農業"}, "level_3": {"options": [{"text": "農業", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "季節", "is_correct": false, "explanation": "意味：季節は「する」ものではない。"}, {"text": "野菜", "is_correct": false, "explanation": "連語：「野菜をする」とは言わない。"}, {"text": "天気", "is_correct": false, "explanation": "意味：天気は人がする仕事ではない。"}], "explanations": {"農業": "正解：文の意味に合う。", "季節": "意味：季節は「する」ものではない。", "野菜": "連語：「野菜をする」とは言わない。", "天気": "意味：天気は人がする仕事ではない。"}, "sentence_index": 0, "correct_answer": "農業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "農業を三冊勉強しています。", "explanation": "助数詞の誤り：農業は「冊」で数えない。"}, {"text": "祖父は農業にしています。", "explanation": "助詞の混同：「農業をしている」が正しい。"}, {"text": "農業を昨日しているつもりです。", "explanation": "活用・アスペクトの誤り：「昨日」と「ている」「つもり」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, 