INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35514, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解：この位置で文法的に成り立つ助詞。"}, {"text": "に", "is_correct": false, "explanation": "「農業に生活する」とは言わず、手段を表す「で」が必要。"}, {"text": "を", "is_correct": false, "explanation": "「生活する」は「農業」を目的語に取らない。"}, {"text": "が", "is_correct": false, "explanation": "「農業が生活している」は主語が不自然。"}], "correct_answer": "で", "explanations": {"で": "正解：この位置で文法的に成り立つ助詞。", "に": "「農業に生活する」とは言わず、手段を表す「で」が必要。", "を": "「生活する」は「農業」を目的語に取らない。", "が": "「農業が生活している」は主語が不自然。"}, "error_tags": {"に": "location_vs_target", "を": "object_marking", "が": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
