INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35528, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地域", "is_correct": true, "explanation": "正解：「ちいき」と読む対象語。"}, {"text": "世紀", "is_correct": false, "explanation": "「せいき」と読む。第一モーラ「ち」が「せ」に変わる一モーラ差。"}, {"text": "定期", "is_correct": false, "explanation": "「ていき」と読む。第一モーラ「ち」が「て」に変わる一モーラ差。"}, {"text": "知識", "is_correct": false, "explanation": "「ちしき」と読む。第二モーラ「い」が「し」に変わる一モーラ差。"}, {"text": "知育", "is_correct": false, "explanation": "「ちいく」と読む。第三モーラ「き」が「く」に変わる一モーラ差。"}], "explanations": {"地域": "正解：「ちいき」と読む対象語。", "世紀": "「せいき」と読む。第一モーラ「ち」が「せ」に変わる一モーラ差。", "定期": "「ていき」と読む。第一モーラ「ち」が「て」に変わる一モーラ差。", "知識": "「ちしき」と読む。第二モーラ「い」が「し」に変わる一モーラ差。", "知育": "「ちいく」と読む。第三モーラ「き」が「く」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "地域"}, "level_3": {"options": [{"text": "地域", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "部屋", "is_correct": false, "explanation": "意味：部屋の中に雪がたくさん降ることはない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "意味：鉛筆は場所ではない。"}, {"text": "料理", "is_correct": false, "explanation": "連語：「料理は雪が降る」とは結びつかない。"}], "explanations": {"地域": "正解：文の意味に合う。", "部屋": "意味：部屋の中に雪がたくさん降ることはない。", "鉛筆": "意味：鉛筆は場所ではない。", "料理": "連語：「料理は雪が降る」とは結びつかない。"}, "sentence_index": 0, "correct_answer": "地域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地域を言葉が少し違う。", "explanation": "助詞の混同：「地域によって」が正しい。"}, {"text": "一冊の地域では言葉が違う。", "explanation": "助数詞の誤り：地域を「冊」で数えない。"}, {"text": "地域にとって言葉が少し違う。", "explanation": "表現の混同：違いの基準を表すのは「によって」で、「にとって」は立場を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
