INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35528, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "地域", "is_correct": true, "explanation": "正解：「ちいき」と読む対象語。"}, {"text": "冷気", "is_correct": false, "explanation": "「れいき」と読む。第一モーラ「ち」が「れ」に変わる一モーラ差。"}, {"text": "英気", "is_correct": false, "explanation": "「えいき」と読む。第一モーラ「ち」が「え」に変わる一モーラ差。"}, {"text": "知識", "is_correct": false, "explanation": "「ちしき」と読む。第二モーラ「い」が「し」に変わる一モーラ差。"}, {"text": "定期", "is_correct": false, "explanation": "「ていき」と読む。第一モーラ「ち」が「て」に変わる一モーラ差。"}], "explanations": {"地域": "正解：「ちいき」と読む対象語。", "冷気": "「れいき」と読む。第一モーラ「ち」が「れ」に変わる一モーラ差。", "英気": "「えいき」と読む。第一モーラ「ち」が「え」に変わる一モーラ差。", "知識": "「ちしき」と読む。第二モーラ「い」が「し」に変わる一モーラ差。", "定期": "「ていき」と読む。第一モーラ「ち」が「て」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "地域"}, "level_3": {"options": [{"text": "地域", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "時間", "is_correct": false, "explanation": "意味：時間に「住む」ことはできない。"}, {"text": "意見", "is_correct": false, "explanation": "意味：意見は住む場所ではない。"}, {"text": "料理", "is_correct": false, "explanation": "連語：「料理に住む」とは言わない。"}], "explanations": {"地域": "正解：文の意味に合う。", "時間": "意味：時間に「住む」ことはできない。", "意見": "意味：意見は住む場所ではない。", "料理": "連語：「料理に住む」とは言わない。"}, "sentence_index": 6, "correct_answer": "地域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大雨で一部の地域を停電した。", "explanation": "助詞の混同：「停電する」の主語は「が」で示す。"}, {"text": "大雨で一本の地域が停電した。", "explanation": "助数詞の誤り：地域を「本」で数えない。"}, {"text": "大雨で一部の地域が明日停電した。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「した」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
