INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35541, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "収穫", "is_correct": true, "explanation": "正解：「しゅうかく」と読む対象語。"}, {"text": "習慣", "is_correct": false, "explanation": "「しゅうかん」と読む。第四モーラ「く」が「ん」に変わる一モーラ差。"}, {"text": "聴覚", "is_correct": false, "explanation": "「ちょうかく」と読む。第一モーラ「しゅ」が「ちょ」に変わる一モーラ差。"}, {"text": "就学", "is_correct": false, "explanation": "「しゅうがく」と読む。「か」と「が」の清濁の違い。"}, {"text": "集会", "is_correct": false, "explanation": "「しゅうかい」と読む。第四モーラ「く」が「い」に変わる一モーラ差。"}], "explanations": {"収穫": "正解：「しゅうかく」と読む対象語。", "習慣": "「しゅうかん」と読む。第四モーラ「く」が「ん」に変わる一モーラ差。", "聴覚": "「ちょうかく」と読む。第一モーラ「しゅ」が「ちょ」に変わる一モーラ差。", "就学": "「しゅうがく」と読む。「か」と「が」の清濁の違い。", "集会": "「しゅうかい」と読む。第四モーラ「く」が「い」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "収穫"}, "level_3": {"options": [{"text": "収穫", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "意味：米の色は「多い」で表さない。"}, {"text": "味", "is_correct": false, "explanation": "連語：「味が多い」とは言わない。"}, {"text": "形", "is_correct": false, "explanation": "意味：形は量ではないので「多い」と合わない。"}], "explanations": {"収穫": "正解：文の意味に合う。", "色": "意味：米の色は「多い」で表さない。", "味": "連語：「味が多い」とは言わない。", "形": "意味：形は量ではないので「多い」と合わない。"}, "sentence_index": 0, "correct_answer": "収穫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "収穫を前に機械を準備する。", "explanation": "助詞の混同：「収穫の前に」が正しい。"}, {"text": "三台の収穫の前に準備する。", "explanation": "助数詞の誤り：収穫を「台」で数えない。"}, {"text": "収穫の前に機械を昨日準備する。", "explanation": "活用・アスペクトの誤り：「昨日」と現在形「準備する」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, vali