INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35550, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "他", "is_correct": true, "explanation": "正解：「ほか」と読む対象語。"}, {"text": "墓", "is_correct": false, "explanation": "「はか」と読む。第一モーラ「ほ」が「は」に変わる一モーラ差。"}, {"text": "星", "is_correct": false, "explanation": "「ほし」と読む。第二モーラ「か」が「し」に変わる一モーラ差。"}, {"text": "骨", "is_correct": false, "explanation": "「ほね」と読む。第二モーラ「か」が「ね」に変わる一モーラ差。"}, {"text": "坂", "is_correct": false, "explanation": "「さか」と読む。第一モーラ「ほ」が「さ」に変わる一モーラ差。"}], "explanations": {"他": "正解：「ほか」と読む対象語。", "墓": "「はか」と読む。第一モーラ「ほ」が「は」に変わる一モーラ差。", "星": "「ほし」と読む。第二モーラ「か」が「し」に変わる一モーラ差。", "骨": "「ほね」と読む。第二モーラ「か」が「ね」に変わる一モーラ差。", "坂": "「さか」と読む。第一モーラ「ほ」が「さ」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "他"}, "level_3": {"options": [{"text": "他", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "机", "is_correct": false, "explanation": "意味：机の色を店で尋ねる文にならない。"}, {"text": "犬", "is_correct": false, "explanation": "意味：犬の色が「ある」かを店で聞くのは不自然。"}, {"text": "雨", "is_correct": false, "explanation": "連語：「雨の色はありますか」とは言わない。"}], "explanations": {"他": "正解：文の意味に合う。", "机": "意味：机の色を店で尋ねる文にならない。", "犬": "意味：犬の色が「ある」かを店で聞くのは不自然。", "雨": "連語：「雨の色はありますか」とは言わない。"}, "sentence_index": 0, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他を人の意見も聞いてみよう。", "explanation": "助詞の混同：名詞を修飾するには「他の人」とする。"}, {"text": "他の一冊の人の意見も聞いてみよう。", "explanation": "助数詞の誤り：人を「冊」で数えない。"}, {"text": "他の人の意見も昨日聞いてみよう。", "explanation": "活用・アスペクトの誤り：「昨日」と意志形「みよう」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation