INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35550, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "他", "is_correct": true, "explanation": "正解：「ほか」と読む対象語。"}, {"text": "矛", "is_correct": false, "explanation": "「ほこ」と読む。第二モーラ「か」が「こ」に変わる一モーラ差。"}, {"text": "本", "is_correct": false, "explanation": "「ほん」と読む。第二モーラ「か」が「ん」に変わる一モーラ差。"}, {"text": "墓", "is_correct": false, "explanation": "「はか」と読む。第一モーラ「ほ」が「は」に変わる一モーラ差。"}, {"text": "星", "is_correct": false, "explanation": "「ほし」と読む。第二モーラ「か」が「し」に変わる一モーラ差。"}], "explanations": {"他": "正解：「ほか」と読む対象語。", "矛": "「ほこ」と読む。第二モーラ「か」が「こ」に変わる一モーラ差。", "本": "「ほん」と読む。第二モーラ「か」が「ん」に変わる一モーラ差。", "墓": "「はか」と読む。第一モーラ「ほ」が「は」に変わる一モーラ差。", "星": "「ほし」と読む。第二モーラ「か」が「し」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "他"}, "level_3": {"options": [{"text": "他", "is_correct": true, "explanation": "正解：文の意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "意味：「色の日」は行ける日を表さない。"}, {"text": "声", "is_correct": false, "explanation": "意味：声は日を区別しない。"}, {"text": "水", "is_correct": false, "explanation": "連語：「水の日なら行けます」とは言わない。"}], "explanations": {"他": "正解：文の意味に合う。", "色": "意味：「色の日」は行ける日を表さない。", "声": "意味：声は日を区別しない。", "水": "連語：「水の日なら行けます」とは言わない。"}, "sentence_index": 6, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "それは他の店を買いました。", "explanation": "助詞の混同：買う場所は「で」で示す。"}, {"text": "それは他の一匹の店で買いました。", "explanation": "助数詞の誤り：店を「匹」で数えない。"}, {"text": "それは他の店で明日買いました。", "explanation": "活用・アスペクトの誤り：「明日」と過去形「買いました」が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d3debff-4f68-4171-9deb-c487476f55d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.valida