INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35558, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の国ではない、ほかの国のことです。", "primary_collocate": null, "pronunciation": "がいこく", "ipa": "ɡaikokɯ", "syllable_count": 4, "sentences": [{"text": "姉は来年、外国で働くつもりだ。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国の料理を食べてみたい。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "この町には外国から来た人が多い。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国はどこも楽しそうに見える。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "兄は外国に住んでいる。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国へ行くにはパスポートがいる。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "私はまだ外国に行ったことがない。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国の友だちに手紙を書いた。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国のお金は形がちがう。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "父は仕事で外国をよく回っている。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}], "morphological_forms": [{"form": "外国人", "label": "派生"}, {"form": "外国語", "label": "派生"}, {"form": "か国", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 自分の国以外のほかの国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b0fdaf