INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35559, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の属する国以外の国。他国。", "primary_collocate": null, "pronunciation": "がいこく", "ipa": "ɡaikokɯ", "syllable_count": 4, "sentences": [{"text": "日本は多くの外国と貿易をしている。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国との交流が年々増えている。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国の文化を知るのはおもしろい。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "彼は外国で日本語を教えている。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国から多くの観光客が来る。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国のニュースを毎朝見ている。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国に比べて物価が高いと言われる。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "この本は外国でも人気がある。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "外国は日本の技術に注目している。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}, {"text": "大学で外国の歴史を学んでいる。", "target_word": "外国", "complexity_tier": "T3", "furigana": "がいこく", "sentence_source": "generated"}], "morphological_forms": [{"form": "外国人", "label": "派生"}, {"form": "外国語", "label": "派生"}, {"form": "か国", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 自分が属する国以外の他国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '