INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35570, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いちばんあと", "primary_collocate": null, "pronunciation": "さいご", "ipa": "saiɡo", "syllable_count": 3, "sentences": [{"text": "最後の問題がいちばん難しかった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "私は列の最後に並んだ。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後まであきらめずに走った。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "ケーキの最後の一つを弟が食べた。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後に部屋の電気を消してね。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "この歌が今日の最後です。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後は笑って別れることができた。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "映画の最後で主人公が泣いていた。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "彼女が最後に教室を出た。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後のバスに間に合わなかった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}], "morphological_forms": [{"form": "最後に", "label": "派生"}, {"form": "最後まで", "label": "派生"}, {"form": "最後の", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 順番のいちばんあと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b0fdafa-5918-4f21-9ed8-620e1ce8821d