INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35571, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の順序や時間の終わり。最後の部分。", "primary_collocate": null, "pronunciation": "さいご", "ipa": "saiɡo", "syllable_count": 3, "sentences": [{"text": "試合の最後に逆転ゴールが決まった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "本の最後を先に読んでしまった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "授業の最後に小テストがある。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "夏休みの最後は宿題で忙しかった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後まで話を聞いてください。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "手紙の最後に名前を書く。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "会議の最後で次の予定を決めた。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "今年の最後に旅行へ行く予定だ。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "物語の最後は意外だった。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}, {"text": "最後が一番大事だと先生は言った。", "target_word": "最後", "complexity_tier": "T3", "furigana": "さいご", "sentence_source": "generated"}], "morphological_forms": [{"form": "最後に", "label": "派生"}, {"form": "最後まで", "label": "派生"}, {"form": "最後の", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の順序や時間の終わりの部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b0fdafa-5918