INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35584, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "お金がたくさんあって、生活に困らないこと。", "primary_collocate": null, "pronunciation": "ふゆう", "ipa": "ɸɯjɯː", "syllable_count": 3, "sentences": [{"text": "彼は富裕な家に生まれた。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "その村は昔から富裕だった。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な人ほど寄付をするとは限らない。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "祖父は商売で富裕になった。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "この地区には富裕な家庭が多い。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な国にも困っている人はいる。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "彼の家は富裕で、大きな庭がある。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な商人が町に学校を建てた。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "国が富裕になると生活も変わる。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "昔、この町は漁業で富裕だった。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}], "morphological_forms": [{"form": "富裕な", "label": "活用"}, {"form": "富裕だ", "label": "活用"}, {"form": "富裕に", "label": "活用"}, {"form": "富裕層", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | お金が多く生活に困らないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', '