INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35585, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "財産が多く、経済的に余裕のある状態。", "primary_collocate": null, "pronunciation": "ふゆう", "ipa": "ɸɯjɯː", "syllable_count": 3, "sentences": [{"text": "富裕な家庭の子どもが留学した。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な人々が旅行を楽しんでいる。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "その国は石油で富裕になった。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "彼女の家族はとても富裕だ。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な暮らしにあこがれる人は多い。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な国と貧しい国の差が広がる。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕でも幸せとは限らない。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な投資家が会社を買った。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "町が富裕になり道路が広がった。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}, {"text": "富裕な客のためのホテルが建った。", "target_word": "富裕", "complexity_tier": "T3", "furigana": "ふゆう", "sentence_source": "generated"}], "morphological_forms": [{"form": "富裕な", "label": "活用"}, {"form": "富裕だ", "label": "活用"}, {"form": "富裕に", "label": "活用"}, {"form": "富裕層", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 財産が多く経済的に余裕がある状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', '