INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35558, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外国", "is_correct": true, "explanation": "がいこく。聞こえた語そのものです。"}, {"text": "開国", "is_correct": false, "explanation": "かいこく。「が」と「か」の清濁の違い。"}, {"text": "骸骨", "is_correct": false, "explanation": "がいこつ。最後の「く」が「つ」に変わる一モーラ差。"}, {"text": "外交", "is_correct": false, "explanation": "がいこう。最後の「く」が「う」に変わる一モーラ差。"}], "explanations": {"外国": "がいこく。聞こえた語そのものです。", "開国": "かいこく。「が」と「か」の清濁の違い。", "骸骨": "がいこつ。最後の「く」が「つ」に変わる一モーラ差。", "外交": "がいこう。最後の「く」が「う」に変わる一モーラ差。"}, "sentence_index": null, "correct_answer": "外国"}, "level_3": {"options": [{"text": "外国", "is_correct": true, "explanation": "文脈に合う正解です。"}, {"text": "天気", "is_correct": false, "explanation": "「天気で働く」は意味が通じません。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆で働く」は場所を表せず意味が通りません。"}, {"text": "気持ち", "is_correct": false, "explanation": "「気持ちで働く」は文意に合いません。"}], "explanations": {"外国": "文脈に合う正解です。", "天気": "「天気で働く」は意味が通じません。", "鉛筆": "「鉛筆で働く」は場所を表せず意味が通りません。", "気持ち": "「気持ちで働く」は文意に合いません。"}, "sentence_index": 0, "correct_answer": "外国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国が大きくあくびをして眠った。", "explanation": "外国は国なので、あくびをしたり眠ったりしません。"}, {"text": "私は毎朝、外国を飲んでいる。", "explanation": "外国は国なので飲むものではありません。"}, {"text": "この鉛筆はとても外国だ。", "explanation": "外国は名詞で、性質を表す述語にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd11760-6bc7-42e6-8224-24795c91adb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
