INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35558, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞と名詞をつなぐ「の」です。"}, {"text": "を", "is_correct": false, "explanation": "「外国を料理」は名詞をつなげられません。"}, {"text": "に", "is_correct": false, "explanation": "「外国に料理」は文が成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「外国が料理を」では外国が食べる人のようになり不自然です。"}], "correct_answer": "の", "explanations": {"の": "名詞と名詞をつなぐ「の」です。", "を": "「外国を料理」は名詞をつなげられません。", "に": "「外国に料理」は文が成り立ちません。", "が": "「外国が料理を」では外国が食べる人のようになり不自然です。"}, "error_tags": {"を": "object_marking", "に": "location_vs_target", "が": "topic_vs_subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd11760-6bc7-42e6-8224-24795c91adb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
