INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35584, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富裕", "is_correct": true, "explanation": "ふゆう。聞こえた語です。"}, {"text": "不要", "is_correct": false, "explanation": "ふよう。「ゆ」が「よ」になる一モーラ差。"}, {"text": "冬", "is_correct": false, "explanation": "ふゆ。最後の長音がない長短の違い。"}, {"text": "普通", "is_correct": false, "explanation": "ふつう。「ゆ」が「つ」になる一モーラ差。"}], "explanations": {"富裕": "ふゆう。聞こえた語です。", "不要": "ふよう。「ゆ」が「よ」になる一モーラ差。", "冬": "ふゆ。最後の長音がない長短の違い。", "普通": "ふつう。「ゆ」が「つ」になる一モーラ差。"}, "sentence_index": null, "correct_answer": "富裕"}, "level_3": {"options": [{"text": "富裕", "is_correct": true, "explanation": "文脈に合う正解です。"}, {"text": "鉛筆", "is_correct": false, "explanation": "「鉛筆な家」は成り立ちません。"}, {"text": "走る", "is_correct": false, "explanation": "動詞は「な家」の前に入りません。"}, {"text": "昨日", "is_correct": false, "explanation": "「昨日な家」は成り立ちません。"}], "explanations": {"富裕": "文脈に合う正解です。", "鉛筆": "「鉛筆な家」は成り立ちません。", "走る": "動詞は「な家」の前に入りません。", "昨日": "「昨日な家」は成り立ちません。"}, "sentence_index": 0, "correct_answer": "富裕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この水はとても富裕で冷たい。", "explanation": "富裕は水の様子を表しません。"}, {"text": "彼はお金がなくて富裕だ。", "explanation": "お金がないのに富裕は矛盾です。"}, {"text": "富裕を三つ買ってきた。", "explanation": "富裕は物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dd11760-6bc7-42e6-8224-24795c91adb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
