INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35610, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あることの、うしろにかくれたわけ。", "primary_collocate": null, "pronunciation": "はいご", "ipa": "haiɡo", "syllable_count": 3, "sentences": [{"text": "事件の背後には何があるのか。", "target_word": "背後", "complexity_tier": "T3", "furigana": "じけん はいご なに", "sentence_source": "generated"}, {"text": "その決定の背後に理由がある。", "target_word": "背後", "complexity_tier": "T3", "furigana": "けってい はいご りゆう", "sentence_source": "generated"}, {"text": "背後の事情を知りたい。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はいご じじょう しりたい", "sentence_source": "generated"}, {"text": "人気の背後には努力があった。", "target_word": "背後", "complexity_tier": "T3", "furigana": "にんき はいご どりょく", "sentence_source": "generated"}, {"text": "問題の背後を考えてみよう。", "target_word": "背後", "complexity_tier": "T3", "furigana": "もんだい はいご かんがえて", "sentence_source": "generated"}, {"text": "背後にある考えが大切だ。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はいご かんがえ たいせつ", "sentence_source": "generated"}, {"text": "うわさの背後に誰かがいる。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はいご だれ", "sentence_source": "generated"}, {"text": "その話の背後は複雑だ。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はなし はいご ふくざつ", "sentence_source": "generated"}, {"text": "けんかの背後に不安があった。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はいご ふあん", "sentence_source": "generated"}, {"text": "背後の理由を調べている。", "target_word": "背後", "complexity_tier": "T3", "furigana": "はいご りゆう しらべて", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 物事の裏にかくれた事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6dd08a-4c5e-4106-a42e-4f580c7a8547') ON CONFLICT