INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35622, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かが始まって、終わりのところまで続くこと。", "primary_collocate": null, "pronunciation": "いたる", "ipa": "itaɾɯ", "syllable_count": 3, "sentences": [{"text": "朝から夜に至るまで働いた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "あさ よる いたる はたらいた", "sentence_source": "generated"}, {"text": "子どもから大人に至るまで楽しめる。", "target_word": "至る", "complexity_tier": "T3", "furigana": "こ おとな いたる たのしめる", "sentence_source": "generated"}, {"text": "服から靴に至るまで新しい。", "target_word": "至る", "complexity_tier": "T3", "furigana": "ふく くつ いたる あたら", "sentence_source": "generated"}, {"text": "話し合いは朝から夜中に至るまで続いた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "はなしあい あさ よなか いたる つづいた", "sentence_source": "generated"}, {"text": "計画から完成に至るまで一年だ。", "target_word": "至る", "complexity_tier": "T3", "furigana": "けいかく かんせい いたる いちねん", "sentence_source": "generated"}, {"text": "小さな点に至るまで調べた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "ちい てん いたる しらべた", "sentence_source": "generated"}, {"text": "工事は春から秋に至るまで続いた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "こうじ はる あき いたる つづいた", "sentence_source": "generated"}, {"text": "食事から寝る時間に至るまで決まっている。", "target_word": "至る", "complexity_tier": "T3", "furigana": "しょくじ ね じかん いたる き", "sentence_source": "generated"}, {"text": "祭りは朝から深夜に至った。", "target_word": "至った", "complexity_tier": "T3", "furigana": "まつ あさ しんや いたった", "sentence_source": "generated"}, {"text": "頭から足に至るまでぬれた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "あたま あし いたる", "sentence_source": "generated"}], "morphological_forms": [{"form": "至った", "label": "活用"}, {"form": "至って", "label": "活用"}, {"form": "至らない", "label": "活用"}, {"form": "至り", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 始めから終わりまで続き及ぶ", "colloc