INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35623, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある地点や状態から、別の地点や状態にまで及ぶこと。", "primary_collocate": null, "pronunciation": "いたる", "ipa": "itaɾɯ", "syllable_count": 3, "sentences": [{"text": "この道は駅に至る。", "target_word": "至る", "complexity_tier": "T3", "furigana": "みち えき いたる", "sentence_source": "generated"}, {"text": "話し合いで結論に至った。", "target_word": "至った", "complexity_tier": "T3", "furigana": "はなしあ けつろん いたった", "sentence_source": "generated"}, {"text": "山頂に至る道は細い。", "target_word": "至る", "complexity_tier": "T3", "furigana": "さんちょう いたる みち ほそ", "sentence_source": "generated"}, {"text": "小さなミスが事故に至った。", "target_word": "至った", "complexity_tier": "T3", "furigana": "ちい じこ いたった", "sentence_source": "generated"}, {"text": "まだ合意に至っていない。", "target_word": "至って", "complexity_tier": "T3", "furigana": "ごうい いたって", "sentence_source": "generated"}, {"text": "けがは大事に至らなかった。", "target_word": "至らなかった", "complexity_tier": "T3", "furigana": "だいじ いたらなかった", "sentence_source": "generated"}, {"text": "川は海に至る。", "target_word": "至る", "complexity_tier": "T3", "furigana": "かわ うみ いたる", "sentence_source": "generated"}, {"text": "その考えに至った理由を話す。", "target_word": "至った", "complexity_tier": "T3", "furigana": "かんが いたった りゆう はな", "sentence_source": "generated"}, {"text": "国境に至る道を歩いた。", "target_word": "至る", "complexity_tier": "T3", "furigana": "こっきょう いたる みち ある", "sentence_source": "generated"}, {"text": "彼は答えに至った。", "target_word": "至った", "complexity_tier": "T3", "furigana": "かれ こた いたった", "sentence_source": "generated"}], "morphological_forms": [{"form": "至った", "label": "活用"}, {"form": "至って", "label": "活用"}, {"form": "至らない", "label": "活用"}, {"form": "至り", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | ある地点や状態に行き着く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d6dd08a-4c5e-4106-a42e-4f580c7a8547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35636, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを作り出すこと。", "primary_collocate": null, "pronunciation": "なす", "ipa": "nasɯ", "syllable_count": 2, "sentences": [{"text": "彼は一代で財を成した。", "target_word": "成した", "complexity_tier": "T3", "furigana": "かれ いちだい ざい なした", "sentence_source": "generated"}, {"text": "彼は商売で財を成して有名になった。", "target_word": "成して", "complexity_tier": "T3", "furigana": "かれ しょうばい ざい なして ゆうめい", "sentence_source": "generated"}, {"text": "彼女は小説家として名を成している。", "target_word": "成して", "complexity_tier": "T3", "furigana": "かのじょ しょうせつか な なして", "sentence_source": "generated"}, {"text": "父は小さな店から大きな富を成した。", "target_word": "成した", "complexity_tier": "T3", "furigana": "ちち ちいさな みせ おおきな とみ なした", "sentence_source": "generated"}, {"text": "彼は若くして名を成す。", "target_word": "成す", "complexity_tier": "T3", "furigana": "かれ わかくして な なす", "sentence_source": "generated"}, {"text": "彼女は一つの流派を成した。", "target_word": "成した", "complexity_tier": "T3", "furigana": "かのじょ ひと りゅうは なした", "sentence_source": "generated"}, {"text": "その画家は若い頃すでに名を成していた。", "target_word": "成して", "complexity_tier": "T3", "furigana": "がか わかい ころ な なして", "sentence_source": "generated"}, {"text": "努力で家を成す人もいる。", "target_word": "成す", "complexity_tier": "T3", "furigana": "どりょく いえ なす ひと", "sentence_source": "generated"}, {"text": "彼は新しい学派を成した学者だ。", "target_word": "成した", "complexity_tier": "T3", "furigana": "かれ あたらしい がくは なした がくしゃ", "sentence_source": "generated"}, {"text": "彼は音楽で名を成した。", "target_word": "成した", "complexity_tier": "T3", "furigana": "かれ おんがく な なした", "sentence_source": "generated"}], "morphological_forms": [{"form": "成した", "label": "活用"}, {"form": "成して", "label": "活用"}, {"form": "成さない", "label": "活用"}, {"form": "成し遂げる", "label": "派生"}], "register": "formal", "sense_fingerprint": "動詞 | 新しいものを作り出す", "collocate_gr