INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35598, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "選ぶ", "is_correct": true, "explanation": "正解。"}, {"text": "偉い", "is_correct": false, "explanation": "えらい：最後の「ぶ」が「い」に変わる一モーラ差"}, {"text": "エラー", "is_correct": false, "explanation": "えらー：最後の「ぶ」が長音に変わる"}, {"text": "クラブ", "is_correct": false, "explanation": "くらぶ：最初の「え」が「く」に変わる一モーラ差"}], "explanations": {"選ぶ": "正解。", "偉い": "えらい：最後の「ぶ」が「い」に変わる一モーラ差", "エラー": "えらー：最後の「ぶ」が長音に変わる", "クラブ": "くらぶ：最初の「え」が「く」に変わる一モーラ差"}, "sentence_index": null, "correct_answer": "選ぶ"}, "level_3": {"options": [{"text": "選んで", "is_correct": true, "explanation": "正解。"}, {"text": "食べて", "is_correct": false, "explanation": "意味：色は食べるものではない"}, {"text": "歩いて", "is_correct": false, "explanation": "項構造：「歩く」は「色を」を目的語にとれない"}, {"text": "眠って", "is_correct": false, "explanation": "項構造：自動詞で「を」の目的語をとらない"}], "explanations": {"選んで": "正解。", "食べて": "意味：色は食べるものではない", "歩いて": "項構造：「歩く」は「色を」を目的語にとれない", "眠って": "項構造：自動詞で「を」の目的語をとらない"}, "sentence_index": 0, "correct_answer": "選んで"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨が空から選んできた。", "explanation": "意味の誤り：「選ぶ」は降る意味ではない"}, {"text": "猫で好きなえさを選んだ。", "explanation": "助詞の誤り：選ぶ主体は「が」で表す"}, {"text": "風が木の葉を選んだ。", "explanation": "意味の誤り：風は意志をもって選ぶ主体にならない"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7927e4-bb91-422a-9ba6-a4898d681fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35598, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "好きな色を選びてください。", "corrected_sentence": "好きな色を選んでください。", "error_description": "「選ぶ」のて形は「選んで」で、「選びて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "選んだ", "is_correct": true, "explanation": "正解。"}, {"text": "選んだら", "is_correct": false, "explanation": "条件形は後に続く文が必要"}, {"text": "選び", "is_correct": false, "explanation": "連用形のままでは文が終わらない"}, {"text": "選べば", "is_correct": false, "explanation": "条件形は後に続く文が必要"}], "correct_form": "選んだ", "base_form": "選ぶ", "form_label": "た形（過去）", "sentence_index": 1, "explanations": {"選んだ": "正解。", "選んだら": "条件形は後に続く文が必要", "選び": "連用形のままでは文が終わらない", "選べば": "条件形は後に続く文が必要"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7927e4-bb91-422a-9ba6-a4898d681fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35598, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。"}, {"text": "が", "is_correct": false, "explanation": "「選ぶ」の目的語は「が」で標示できない"}, {"text": "に", "is_correct": false, "explanation": "着点を表し、選ぶ対象を示せない"}, {"text": "へ", "is_correct": false, "explanation": "方向を表し、この位置では非文"}], "correct_answer": "を", "explanations": {"を": "正解。", "が": "「選ぶ」の目的語は「が」で標示できない", "に": "着点を表し、選ぶ対象を示せない", "へ": "方向を表し、この位置では非文"}, "error_tags": {"が": "object_marking", "に": "location_vs_target", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f7927e4-bb91-422a-9ba6-a4898d681fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
