INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35642, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "植物を畑などで育てること。", "primary_collocate": null, "pronunciation": "さいばい", "ipa": "saibai", "syllable_count": 4, "sentences": [{"text": "祖父は畑でトマトの栽培をしている。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "そふ はたけ さいばい", "sentence_source": "generated"}, {"text": "この村では米の栽培が盛んだ。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "むら こめ さいばい さか", "sentence_source": "generated"}, {"text": "イチゴを栽培するのは楽しい。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "さいばい たの", "sentence_source": "generated"}, {"text": "栽培した野菜を友達にあげた。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "さいばい やさい ともだち", "sentence_source": "generated"}, {"text": "学校で花の栽培を始めた。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "がっこう はな さいばい はじ", "sentence_source": "generated"}, {"text": "この地方は茶の栽培で有名だ。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "ちほう ちゃ さいばい ゆうめい", "sentence_source": "generated"}, {"text": "家でハーブを栽培している。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "いえ さいばい", "sentence_source": "generated"}, {"text": "栽培の方法を本で調べた。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "さいばい ほうほう ほん しら", "sentence_source": "generated"}, {"text": "寒い国ではバナナの栽培は難しい。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "さむ くに さいばい むずか", "sentence_source": "generated"}, {"text": "兄はキノコの栽培に興味がある。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "あに さいばい きょうみ", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽培する", "label": "派生"}, {"form": "栽培者", "label": "派生"}, {"form": "水耕栽培", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 植物を畑などで育てること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this