INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35670, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "生き物が古い皮をぬいで、新しい皮になること。", "primary_collocate": null, "pronunciation": "だっぴ", "ipa": "dappi", "syllable_count": 3, "sentences": [{"text": "ヘビが脱皮するところを見た。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ み", "sentence_source": "generated"}, {"text": "カニは脱皮して大きくなる。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ おお", "sentence_source": "generated"}, {"text": "脱皮した皮が木に残っていた。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ かわ き のこ", "sentence_source": "generated"}, {"text": "セミの脱皮は夜に行われる。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ よる おこな", "sentence_source": "generated"}, {"text": "トカゲの脱皮を観察した。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ かんさつ", "sentence_source": "generated"}, {"text": "脱皮の前は虫があまり動かない。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ まえ むし うご", "sentence_source": "generated"}, {"text": "エビは何度も脱皮をする。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "なんど だっぴ", "sentence_source": "generated"}, {"text": "脱皮したばかりのカニは柔らかい。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ やわ", "sentence_source": "generated"}, {"text": "飼っている虫が脱皮を始めた。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "か むし だっぴ はじ", "sentence_source": "generated"}, {"text": "脱皮に失敗する虫もいる。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ しっぱい むし", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱皮する", "label": "派生"}, {"form": "脱皮した", "label": "活用"}, {"form": "脱皮殻", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 生き物が古い皮をぬぐこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d905ccf-84f2-4ecd-975e-d7bd749cc529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35671, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "動物や昆虫が、成長するときに古い外皮を脱ぎ捨てて新しい皮に変わること。", "primary_collocate": null, "pronunciation": "だっぴ", "ipa": "dappi", "syllable_count": 3, "sentences": [{"text": "幼虫は脱皮して成長する。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "ようちゅう だっぴ せいちょう", "sentence_source": "generated"}, {"text": "ザリガニの脱皮を初めて見た。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ はじ み", "sentence_source": "generated"}, {"text": "昆虫は脱皮をくり返す。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "こんちゅう だっぴ かえ", "sentence_source": "generated"}, {"text": "脱皮の後、体が白くなった。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ あと からだ しろ", "sentence_source": "generated"}, {"text": "ヘビは年に数回脱皮する。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "とし すうかい だっぴ", "sentence_source": "generated"}, {"text": "脱皮した殻を標本にした。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ から ひょうほん", "sentence_source": "generated"}, {"text": "クモも脱皮で大きくなる。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ おお", "sentence_source": "generated"}, {"text": "脱皮中の虫にさわってはいけない。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴちゅう むし", "sentence_source": "generated"}, {"text": "カブトムシの幼虫が脱皮した。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "ようちゅう だっぴ", "sentence_source": "generated"}, {"text": "脱皮には多くの力が必要だ。", "target_word": "脱皮", "complexity_tier": "T3", "furigana": "だっぴ おお ちから ひつよう", "sentence_source": "generated"}], "morphological_forms": [{"form": "脱皮する", "label": "派生"}, {"form": "脱皮して", "label": "活用"}, {"form": "脱皮期", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 成長で古い外皮を脱ぎ捨てる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d905ccf-84f2-4ecd-975e-d7bd749cc529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35680, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所や段階、時間を通って、次へ進むこと。", "primary_collocate": null, "pronunciation": "へる", "ipa": "heɾɯ", "syllable_count": 2, "sentences": [{"text": "豆は多くの工程を経て店に届く。", "target_word": "経", "complexity_tier": "T3", "furigana": "まめ おお こうてい へ みせ とど", "sentence_source": "generated"}, {"text": "長い時間を経て、町は変わった。", "target_word": "経", "complexity_tier": "T3", "furigana": "なが じかん へ まち か", "sentence_source": "generated"}, {"text": "大阪を経て東京へ向かった。", "target_word": "経", "complexity_tier": "T3", "furigana": "おおさか へ とうきょう む", "sentence_source": "generated"}, {"text": "試験を経た人だけが選ばれる。", "target_word": "経", "complexity_tier": "T3", "furigana": "しけん へ ひと えら", "sentence_source": "generated"}, {"text": "三年を経て、やっと完成した。", "target_word": "経", "complexity_tier": "T3", "furigana": "さんねん へ かんせい", "sentence_source": "generated"}, {"text": "色々な経験を経て強くなった。", "target_word": "経", "complexity_tier": "T3", "furigana": "いろいろ けいけん へ つよ", "sentence_source": "generated"}, {"text": "話し合いを経て決まった。", "target_word": "経", "complexity_tier": "T3", "furigana": "はな あ へ き", "sentence_source": "generated"}, {"text": "百年を経た古い家がある。", "target_word": "経", "complexity_tier": "T3", "furigana": "ひゃくねん へ ふる いえ", "sentence_source": "generated"}, {"text": "この手紙は多くの人の手を経た。", "target_word": "経", "complexity_tier": "T3", "furigana": "てがみ おお ひと て へ", "sentence_source": "generated"}, {"text": "練習を経て、上手になった。", "target_word": "経", "complexity_tier": "T3", "furigana": "れんしゅう へ じょうず", "sentence_source": "generated"}], "morphological_forms": [{"form": "経た", "label": "活用"}, {"form": "経て", "label": "活用"}, {"form": "経ない", "label": "活用"}], "register": "formal", "sense_fingerprint": "動詞 | 段階や時間を通って進む", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'