INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35696, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "必要なものを人や場所に与えること。", "primary_collocate": null, "pronunciation": "きょうきゅう", "ipa": "kʲoːkʲɯː", "syllable_count": 4, "sentences": [{"text": "町に水を供給している。", "target_word": "供給", "complexity_tier": "T3", "furigana": "まち みず きょうきゅう", "sentence_source": "generated"}, {"text": "電気の供給が止まった。", "target_word": "供給", "complexity_tier": "T3", "furigana": "でんき きょうきゅう と", "sentence_source": "generated"}, {"text": "野菜の供給が足りない。", "target_word": "供給", "complexity_tier": "T3", "furigana": "やさい きょうきゅう た", "sentence_source": "generated"}, {"text": "工場が部品を供給する。", "target_word": "供給", "complexity_tier": "T3", "furigana": "こうじょう ぶひん きょうきゅう", "sentence_source": "generated"}, {"text": "ガスの供給を再開した。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう さいかい", "sentence_source": "generated"}, {"text": "食料を供給する船が来た。", "target_word": "供給", "complexity_tier": "T3", "furigana": "しょくりょう きょうきゅう ふね き", "sentence_source": "generated"}, {"text": "供給が増えて値段が下がった。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう ふ ねだん さ", "sentence_source": "generated"}, {"text": "供給の問題を話し合った。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう もんだい はな あ", "sentence_source": "generated"}, {"text": "この川は村に水を供給している。", "target_word": "供給", "complexity_tier": "T3", "furigana": "かわ むら みず きょうきゅう", "sentence_source": "generated"}, {"text": "マスクの供給が追いつかない。", "target_word": "供給", "complexity_tier": "T3", "furigana": "きょうきゅう お", "sentence_source": "generated"}], "morphological_forms": [{"form": "供給する", "label": "派生"}, {"form": "供給量", "label": "派生"}, {"form": "供給源", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 必要なものを与えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this s