INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35734, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "答えを出すために考えなければならないこと。また、解決が必要なむずかしいこと。", "primary_collocate": null, "pronunciation": "もんだい", "ipa": "mondai", "syllable_count": 4, "sentences": [{"text": "この問題は難しい。", "target_word": "問題", "complexity_tier": "T3", "furigana": "もんだい むずか", "sentence_source": "generated"}, {"text": "テストの問題を全部解いた。", "target_word": "問題", "complexity_tier": "T3", "furigana": "もんだい ぜんぶ と", "sentence_source": "generated"}, {"text": "問題があれば言ってください。", "target_word": "問題", "complexity_tier": "T3", "furigana": "もんだい い", "sentence_source": "generated"}, {"text": "環境の問題について話し合った。", "target_word": "問題", "complexity_tier": "T3", "furigana": "かんきょう もんだい はな あ", "sentence_source": "generated"}, {"text": "先生が問題を出した。", "target_word": "問題", "complexity_tier": "T3", "furigana": "せんせい もんだい だ", "sentence_source": "generated"}, {"text": "それは大きな問題になった。", "target_word": "問題", "complexity_tier": "T3", "furigana": "おお もんだい", "sentence_source": "generated"}, {"text": "問題の答えがわからない。", "target_word": "問題", "complexity_tier": "T3", "furigana": "もんだい こた", "sentence_source": "generated"}, {"text": "二人で問題を解決した。", "target_word": "問題", "complexity_tier": "T3", "furigana": "ふたり もんだい かいけつ", "sentence_source": "generated"}, {"text": "算数の問題が好きだ。", "target_word": "問題", "complexity_tier": "T3", "furigana": "さんすう もんだい す", "sentence_source": "generated"}, {"text": "時間の問題ではない。", "target_word": "問題", "complexity_tier": "T3", "furigana": "じかん もんだい", "sentence_source": "generated"}], "morphological_forms": [{"form": "問題点", "label": "派生"}, {"form": "問題集", "label": "派生"}, {"form": "一問", "label": "助数詞"}], "register": "plain", "sense_fingerprint": "名詞 | 考えて答えを出すべきこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-