INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35642, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栽培", "is_correct": true, "explanation": "正解。読みは「さいばい」。"}, {"text": "裁判", "is_correct": false, "explanation": "読みは「さいばん」。一モーラだけ違う別の語。"}, {"text": "采配", "is_correct": false, "explanation": "読みは「さいはい」。一モーラだけ違う別の語。"}, {"text": "最大", "is_correct": false, "explanation": "読みは「さいだい」。一モーラだけ違う別の語。"}, {"text": "再開", "is_correct": false, "explanation": "読みは「さいかい」。一モーラだけ違う別の語。"}], "explanations": {"栽培": "正解。読みは「さいばい」。", "裁判": "読みは「さいばん」。一モーラだけ違う別の語。", "采配": "読みは「さいはい」。一モーラだけ違う別の語。", "最大": "読みは「さいだい」。一モーラだけ違う別の語。", "再開": "読みは「さいかい」。一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "栽培"}, "level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "意味：トマトを育てることを表す。"}, {"text": "散歩", "is_correct": false, "explanation": "意味：トマトの散歩はありえない。"}, {"text": "値段", "is_correct": false, "explanation": "項構造：「値段をする」とは言わない。"}, {"text": "到着", "is_correct": false, "explanation": "意味：トマトの到着をしているは不自然。"}], "explanations": {"栽培": "意味：トマトを育てることを表す。", "散歩": "意味：トマトの散歩はありえない。", "値段": "項構造：「値段をする」とは言わない。", "到着": "意味：トマトの到着をしているは不自然。"}, "sentence_index": 0, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は犬を栽培している。", "explanation": "意味：動物には「飼う」を使う。"}, {"text": "母は赤ちゃんを栽培した。", "explanation": "意味：人には「育てる」を使う。"}, {"text": "工場で車を栽培する。", "explanation": "意味：機械は「作る」もので、栽培しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4115bb02-07ca-45b6-975d-267d988536f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
