INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35680, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "経る", "is_correct": true, "explanation": "正解。読みは「へる」。"}, {"text": "張る", "is_correct": false, "explanation": "読みは「はる」。一モーラだけ違う別の語。"}, {"text": "寝る", "is_correct": false, "explanation": "読みは「ねる」。一モーラだけ違う別の語。"}, {"text": "出る", "is_correct": false, "explanation": "読みは「でる」。一モーラだけ違う別の語。"}, {"text": "蹴る", "is_correct": false, "explanation": "読みは「ける」。一モーラだけ違う別の語。"}], "explanations": {"経る": "正解。読みは「へる」。", "張る": "読みは「はる」。一モーラだけ違う別の語。", "寝る": "読みは「ねる」。一モーラだけ違う別の語。", "出る": "読みは「でる」。一モーラだけ違う別の語。", "蹴る": "読みは「ける」。一モーラだけ違う別の語。"}, "sentence_index": null, "correct_answer": "経る"}, "level_3": {"options": [{"text": "経", "is_correct": true, "explanation": "意味：工程を通って店に届く。"}, {"text": "寝", "is_correct": false, "explanation": "項構造：「工程を寝る」は非文。"}, {"text": "着", "is_correct": false, "explanation": "項構造：「工程を着る」は非文。"}, {"text": "煮", "is_correct": false, "explanation": "意味：工程を煮ることはできない。"}], "explanations": {"経": "意味：工程を通って店に届く。", "寝": "項構造：「工程を寝る」は非文。", "着": "項構造：「工程を着る」は非文。", "煮": "意味：工程を煮ることはできない。"}, "sentence_index": 0, "correct_answer": "経"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お腹が経て、ご飯を食べた。", "explanation": "意味：空腹は「減る」で、「経る」ではない。"}, {"text": "彼は駅で友達を経た。", "explanation": "意味：人に会うには「会う」を使う。"}, {"text": "このパンは経る味がする。", "explanation": "用法：「経る」は味を表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4115bb02-07ca-45b6-975d-267d988536f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
